update public.site_content set draft_content = $mc${"rows":[{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"c00fb3de-3c07-4c3a-b134-3e6ca7de1043","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"align":"left","answer":"The Magic Coffin is a fractional people and communications consultancy for scale-ups still building their HR team, with six services: internal communications, employee experience, people operations, a fractional HR business partner, pay transparency and manager enablement. Remote-first from Sweden, working with teams anywhere, from one day a week.","bg_type":"none","bg_url":"https://mbxqjjmjywsxibttjrgr.supabase.co/storage/v1/object/public/editor-images/hero/1788616161229.jpg","body":"Dead meetings.&nbsp;Blood-sucking cultures.&nbsp;Comms that say everything while meaning nothing.&nbsp;We bury all of it, and build something with an actual pulse in its place.","color_label":"","color_tagline":"","label":"Fractional people & comms support for scale-ups building their HR team","subtitle":"","tagline":"Bespoke consulting, trustful retainers, fractional support, and more!","tagline_handwritten":true,"title_accent":"vampires.","title_line1":"Your organisation has","title_line2":"We bring the coffin.","title_lines":["<p>Your organisation has vampires.</p>","<p>We bring the coffin.</p>"],"underline_word":"coffin.","visual_image_alt":"A beam of light splitting into a rainbow through a glass prism","visual_image_url":"https://mbxqjjmjywsxibttjrgr.supabase.co/storage/v1/object/public/editor-images/hero/prism-triangle.jpg","visual_layout":"half_bleed","title_size":"","cta_label":"Book a free consultation","cta_url":"#contact","secondary_cta_label":"See the six services","secondary_cta_url":"/services/"},"id":"eea2126b-d34d-4507-a0bb-664049a06485","type":"hero"}]}],"id":"92206caa-2bbd-40a7-bbec-1ac2d39f0046"}],"id":"row_hero_c88d4c9be183","layout":{"alignment":"left","columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false,"verticalAlign":"middle","spaceTop":"lead","spaceBottom":"none"},"schema_version":3,"strip_title":"Hero"},{"id":"gap-home-proof","schema_version":3,"strip_title":"Proof strip","bg_color":"","column_layout":"custom","customCss":null,"scope":null,"layout":{"alignment":"left","columns":1,"fullWidth":false,"marginTop":0,"marginBottom":0,"paddingTop":56,"paddingBottom":56,"snapEnabled":false,"spaceTop":"none","spaceBottom":"none"},"columns":[{"id":"gap-home-proof-col","cell_direction":"vertical","cells":[{"id":"gap-home-proof-cell","span":{"col":1,"row":1},"layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingTop":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"verticalAlign":"top"},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"id":"gap-home-proof-widget","type":"proof_band","data":{"eyebrow":"Before the coffin: the in-house record","title_lines":[],"body":"","items":[{"value":"36","label":"countries run from one comms function"},{"value":"300K+","label":"internal page views a year"},{"value":"~60%","label":"average live Town Hall attendance"},{"value":"~300","label":"new hires through a rebuilt Buddy Programme"}],"band_style":"deep"}}]}]}]},{"id":"gap-home-world-map","schema_version":3,"strip_title":"World map","bg_color":"","column_layout":"custom","customCss":null,"scope":null,"layout":{"alignment":"left","columns":1,"fullWidth":false,"marginTop":0,"marginBottom":0,"paddingTop":56,"paddingBottom":56,"snapEnabled":false,"spaceTop":"mid","spaceBottom":"none"},"columns":[{"id":"gap-home-world-map-col","cell_direction":"vertical","cells":[{"id":"gap-home-world-map-cell","span":{"col":1,"row":1},"layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingTop":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"verticalAlign":"top"},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"id":"gap-home-world-map-widget","type":"world_map","data":{"eyebrow":"Where the work has travelled","title_lines":["36 countries.","One comms function."],"lede":"Town halls across time zones, onboarding in every office and news that lands the same day wherever people sit. Gold marks internal comms. Purple marks the countries where the work covered HR as well, and green marks the main markets today.","legend_note":"Learning and development: all 36","worked":["Canada","Peru","Ecuador","Brazil","Israel","Italy","Austria","Serbia","Kenya","South Africa","Mozambique","Tanzania","Democratic Republic of the Congo","Thailand","China","India","Cambodia","Indonesia","Japan","Hong Kong","Singapore"],"hr":["United States","Colombia","Mexico","United Kingdom","Netherlands","France","Belgium","Spain","Germany","Switzerland","Denmark","Sweden","Finland","Norway","Australia"],"main":["Sweden","Spain","United Kingdom","United States","Romania"]}}]}]}]},{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"26620ba3-89c8-489f-99c1-82da97412443","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"__design":{"bgColor":"","borderRadius":0,"customCss":"","marginBottom":0,"marginLeft":0,"marginRight":0,"marginTop":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"visibility":{"desktop":true,"mobile":true}},"cards":[{"body":"Internal communications consulting for teams whose messages land flat: audits, strategy and fractional leadership that turn internal comms from noise into something people actually read, trust and act on.","icon":"lucide:Building2","link_url":"/services/internal-communications","title":"Internal Communications","variant":"pillar"},{"body":"Employee experience consulting across the full lifecycle: onboarding design, engagement surveys and journey mapping built around real people, and still working long after week one.","icon":"lucide:Star","link_url":"/services/employee-experience","title":"Employee Experience","variant":"pillar"},{"body":"People operations consulting and HR systems implementation: HRIS workflows, onboarding infrastructure and process design for teams that have outgrown a shared spreadsheet and someone's memory.","icon":"lucide:Settings2","link_url":"/services/people-operations","title":"People Operations","variant":"pillar"},{"body":"Fractional HR Business Partner support and people partnering for founders who need senior judgement on restructures, employee relations and comp decisions, on demand or by the month.","icon":"lucide:HeartHandshake","link_url":"/services/fractional-hrbp","title":"Fractional HRBP","variant":"pillar"},{"body":"Pay transparency consulting for the EU Pay Transparency Directive: job levels, pay bands on gender-neutral criteria, and the words your managers use when someone asks why they're paid what they're paid.","icon":"lucide:Scale","link_url":"/services/pay-transparency","title":"Pay Transparency","variant":"pillar"},{"body":"Manager training and coaching for new managers: a starter kit, small cohorts and one-to-one coaching, so company news reaches every team the same day, whoever their manager is.","icon":"lucide:Users","link_url":"/services/manager-enablement","title":"Manager Enablement","variant":"pillar"}],"color_card_body":"","color_card_title":"","title_lines":["Our services<p></p>"],"marker_style":"pillar_number"},"id":"5fd69806-f231-440e-bfc6-65f9c2f44863","type":"boxed"}]}],"id":"3a5e1a8f-6a59-4488-be84-ee814699605a"}],"id":"dee9cf78-a8b1-4833-8aac-e54056427c69","layout":{"alignment":"left","columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false,"verticalAlign":"middle","spaceTop":"full","spaceBottom":"full"},"schema_version":3,"strip_title":"Our Services"},{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"b388beb7-08e2-4d24-ac11-db7c2d058aa2","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"__design":{"bgColor":"","borderRadius":0,"customCss":"","marginBottom":0,"marginLeft":0,"marginRight":0,"marginTop":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"visibility":{"desktop":true,"mobile":true}},"caption_position":"bottom-right","color_caption_bg":"","color_caption_text":"","color_description":"","color_eyebrow":"","color_title":"","description":"<p>Every organisation we walk into is convinced its problem is unique. It may be. But it is more likely that it is something someone else has been through.</p><p>Yet, bad internal comms, patchy onboarding, processes that only live in one person's head, pay only one person can explain and new managers learning by guesswork all refract the same light: information missing the people who need it, when they need it.</p><p>Our job is to find where that light is getting bent backwards and weave it in the direction you need.</p>","eyebrow":"What we do","floating_caption":"Same light, better angle.","image_alt":"A prism refracting light into clarity and order, symbolising The Magic Coffin's six people and comms services","image_position":"left","image_shape":"default","image_url":"https://mbxqjjmjywsxibttjrgr.supabase.co/storage/v1/object/public/editor-images/gallery/1788704065115-uigsudh32fj.jpg","split_widths":[48,52],"title":"Clarity is not a mood board. It is a discipline.","title_lines":["<p><span class=\"mc-accent\">Clarity</span> &amp;</p>","<p><span class=\"mc-accent\">order.</span></p>"],"panel_style":""},"id":"76b92ef7-4fe4-4aeb-bcc3-8dca37943a95","type":"image_text"}]}],"id":"3bd4b514-c159-4320-8b41-e07bc9eae900"}],"id":"4d1a0c35-96ed-4255-a06e-8e6fd274a5de","layout":{"alignment":"left","columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":56,"paddingTop":56,"snapEnabled":false,"spaceTop":"tight","spaceBottom":"full"},"schema_version":3,"scope":null,"strip_title":"How We Work"},{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"7e3c5caf-fd6b-460e-9d6f-e940231f861f","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"cards":[{"body":"Messages get sent and lost. Onboarding starts strong, then quietly fades. A process runs because one person remembers it, until that person leaves. Small moments, adding up to a real cost that compounds long before anyone puts a name to it.","icon":"lucide:CircleAlert","title":"The problem","variant":"dark"},{"body":"For leaders who carry the mission themselves, at 50 up to 2,000 people, and who let their team turn up to learn something, earn something, or simply feel respected, heard and motivated to succeed. The vampire moment: messages landing flat, onboarding fading after week one, a pay question your managers dread, or a decision too sensitive to make alone. One exception: leadership treating people as a line item.","icon":"lucide:Users","title":"Who this is for","variant":"glass"},{"body":"Social anthropology, sociology, media and communication: three degrees spent studying how people really experience change. Three and a half years running comms and people systems across 36 countries, through three redundancy rounds, watching how news really lands.","icon":"lucide:GraduationCap","title":"A background built for understanding people","variant":"glass"},{"body":"36 countries run simultaneously. Roughly 500 employees supported through three redundancy rounds. 300,000-plus internal page views generated and actually read in a single year, three figures instead of a slogan, because a claim worth trusting comes with a number attached to it.","icon":"lucide:TrendingUp","title":"Numbers instead of adjectives","variant":"glass"},{"body":"Employee experience is the actual work, holding equal weight with every report and roadmap. Feeling heard and feeling cared for matter here as much as any deliverable, the kind of thing that shows up months later as a client who emails back just to say thank you.","icon":"lucide:HeartHandshake","title":"Happy to help, and it shows","variant":"glass"}],"color_card_body":"","color_card_title":"","eyebrow":"Why The Magic Coffin","title_lines":["<p>Here's the problem, and here's the fix.</p>"],"marker_style":"bar","group_label":"The fix"},"id":"db083d65-45be-4f1d-963b-d0d06d461396","type":"boxed"}]}],"id":"83f93590-f981-4978-b2cb-16ed353431f8"}],"id":"d38f6f83-b1d8-40bc-bc1f-24c5dd9e5ae7","layout":{"alignment":"left","columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":56,"paddingTop":56,"snapEnabled":false,"spaceTop":"full","spaceBottom":"full"},"schema_version":3,"scope":null,"strip_title":"Why The Magic Coffin"},{"bg_color":"","column_layout":"custom","columns":[{"cell_direction":"vertical","cells":[{"id":"e0fc92bb-2d6f-4e87-8569-77d2e4ee9b98","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"cards":[{"body":"<div>Our reports are as clear as a glass prism and as sharp as a stake. We make sure that you hear all that is needed to improve your processes: the backbone to how you conduct your business!</div>","icon":"lucide:Search","title":"Precision over pomp","variant":"glass"},{"body":"<div>Behind every strategy is a handwritten insight. Your people are not capital. They are the life-force. And they should feel and know that: they embody the values of your company!</div>","icon":"lucide:BrainCog","title":"The human trace","variant":"glass"},{"body":"<div>We don't just fix the room. We remove the ceiling. Every engagement is a door to something bigger. Your employees' experience and engagement grow ever more expansive: they carry on your mission!</div>","icon":"lucide:Sprout","title":"Expansive horizons","variant":"glass"}],"marker_style":"roman","subtitle":"","subtitle_color":"","title_lines":["<p>Before we shake hands,</p><p><span class=\"mc-accent\">here is what we vow</span></p>"],"eyebrow":"Our vows"},"id":"cc79b1f2-6441-4bdb-98e5-52f82ec3a07e","type":"boxed"}]}],"id":"19484e3a-9f7a-4063-9273-c5d9a281320e"}],"customCss":null,"id":"be49a60c-c590-4b0f-b668-62cd08f01c09","layout":{"alignment":"left","columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false,"spaceTop":"tight","spaceBottom":"none"},"schema_version":3,"scope":null,"strip_title":"Vows"},{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"be1ce647-18b4-414b-94f4-8e0adde9aaac","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"cards":[{"body":"<span style=\"font-family: 'Architects Daughter', cursive\">Now you get why people leave. This is for building the place they stay.</span>","icon":"lucide:Quote","title":"","variant":""}],"color_card_body":"","color_card_title":"","eyebrow":"","title_lines":["<p></p>"],"marker_style":"note"},"id":"79a8828b-d851-4211-ac44-0a0eebeaa1b6","type":"boxed"}]}],"id":"fef0551e-ed2c-4b34-9def-5965be9fb574"}],"id":"6adb1fb7-3fe8-4f3d-9e54-4278e2d46854","layout":{"alignment":"left","columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":56,"paddingTop":56,"snapEnabled":false,"spaceTop":"tight","spaceBottom":"full"},"schema_version":3,"scope":null,"strip_title":"The point"},{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"6811a4fd-f271-480f-9967-36697ac4e7a2","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"body":"<p></p>","cover_image":"https://mbxqjjmjywsxibttjrgr.supabase.co/storage/v1/object/public/media-library/people-blurred-motion-figures-corridor-arches-1788703492024-s4xepo.jpg","cover_image_alt":"Blurred figures walking through an archway corridor, representing the range of questions on internal comms, employee experience and people operations","eyebrow":"FAQ","items":[{"answer":"<p>The Magic Coffin is a fractional people and comms consultancy with six services: internal communications, employee experience, people operations, fractional HR business partnering, pay transparency and manager enablement.</p><p>Built for companies that have outgrown a shared spreadsheet and someone's memory, while still growing towards a full HR department.</p><p>Engagements usually start with an audit (we call it The Autopsy), or with The Grimoire for new managers, and continue either as a fixed project or a monthly retainer.</p>","question":"What does The Magic Coffin actually do?"},{"answer":"<p>Yes. Current and past clients span the UK, US, Australia, Sweden, Germany and Spain.</p><p>The full track record covers 36 markets worked across in total.</p><p>Engagements run remotely by default, with travel for workshops where it earns the trip.</p>","question":"Do you work with companies outside Sweden?"},{"answer":"<p>Fixed projects start from €600. Retainers start from €400 a month, with a three-month minimum.</p><p>Where your engagement lands inside that depends on the pillar and the tier, so every engagement starts with a free 30-minute call, where you get a straight answer including an honest read on fit.</p>","question":"How much does this cost?"},{"answer":"<p>Clients usually sit between 50 and around 2,000 people, right at the point where the People function is straining under growth pressure with everyone too stretched to mind it.</p><p>Pay transparency work starts from 10 people and manager enablement from 20: the EU pay rules apply to employers of every size.</p><p>Mention your size on the call either way. You'll get a straight, honest answer.</p>","question":"We're small. Are we too small for this?"},{"answer":"<p>A project (The Autopsy, The Burial, and their pillar-specific equivalents) has a fixed scope, a fixed timeline and a defined end.</p><p>A retainer (The Resurrection, or The Night School for managers) is ongoing monthly support with a three-month minimum, because real change takes longer than four weeks to land.</p>","question":"What's the difference between a project and a retainer?"},{"answer":"<p>Yes, by design.</p><p>You work directly with the founder from the first call to the final handover: the same person who scopes the work is the one who delivers it.</p>","question":"Is this a one-person consultancy?"},{"answer":"<p>The exact point a symptom stops being a one-off and becomes how things are done here: onboarding that quietly fades after week one, an update people skim once and forget, a process that only lives in someone's head.</p><p>Small and undramatic on their own, which is exactly why growth stalls quietly rather than dramatically, and why the cost only shows up later, once it's already expensive.</p>","question":"What's a \"vampire moment\"?"},{"answer":"<p>Yes. <a href=\"/services/pay-transparency\">Pay Transparency</a> is one of our six services: job levels, pay bands on gender-neutral criteria, a pay-request process and the scripts your managers use, for companies of 10 to 2,000 people.</p><p>It starts with The Autopsy, a check of your job adverts, contracts and pay data against the Directive, country by country, from €750.</p>","question":"Do you help with the EU Pay Transparency Directive?"},{"answer":"<p>Yes. <a href=\"/services/manager-enablement\">Manager Enablement</a> gives new managers a starter kit (The Grimoire), an eight-week cohort of up to 12 peers (The Coven), one-to-one coaching (The Familiar) and a monthly clinic (The Night School).</p><p>It suits companies of 20 to 2,000 people promoting their first or next wave of managers. The kit starts from €900.</p>","question":"Do you train new managers?"}],"subtitle":"If yours isn't here, that's what the free consultation is for.","subtitle_handwritten":true,"title_lines":["<p>Questions people ask before they call.</p>"]},"id":"0aeefe5f-3e8c-45a8-a1fa-45d14faceac0","type":"faq"}]}],"id":"b6ddfeb9-7952-428f-8070-2749f4a2adcf"}],"id":"34044731-e997-439a-ad8d-13749391b3e8","layout":{"alignment":"left","columns":1,"fullWidth":false,"heightMode":"auto","marginBottom":0,"marginTop":0,"overlays":[],"paddingBottom":64,"paddingTop":64,"snapEnabled":false,"spaceTop":"tight","spaceBottom":"none"},"schema_version":3,"scope":null,"strip_title":"FAQ"},{"bg_color":"","column_layout":"custom","columns":[{"cell_direction":"vertical","cells":[{"id":"c0d9acb8-e059-4525-bbcb-59543e114ad9","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"body":"Book a free 30-minute consultation. We'll identify your biggest vampire moment and tell you honestly whether we're the right fit to bury it.","button_text":"Book a free consultation","fields":[{"key":"name","label":"Your name","required":true,"type":"text","visible":true},{"key":"email","label":"Email address","required":true,"type":"email","visible":true},{"key":"company","label":"Company","required":false,"type":"text","visible":true},{"key":"message","label":"Tell us about your vampire moment","required":true,"type":"textarea","visible":true},{"key":"marketing","label":"Keep me updated with insights and articles","required":false,"type":"checkbox","visible":true}],"show_social":false,"success_body":"We aim to respond within 24 hours. Keep an eye out on your mailbox!","success_button":"Send another message","success_heading":"Thanks for making the first step!","title_lines":["<p>Not sure where to start?</p>","<p><span class=\"mc-accent\">Lift the lid first.</span></p>"],"stamp":"Lid off"},"id":"a80525f6-7f2a-4889-92e3-bad76d72e2b7","type":"contact"}]}],"id":"819ce6e7-539b-46c9-b10a-5035c5af7ff3"}],"customCss":null,"id":"a679082b-a629-4e8a-b57b-5f4743c44d3f","layout":{"alignment":"left","columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false,"spaceTop":"full","spaceBottom":"full"},"schema_version":3,"scope":null,"strip_title":"Contact"}]}$mc$::jsonb where section_key = 'page_rows';
update public.site_content set draft_content = $mc${"blog_categories":[{"bgColor":"#E5C54F","label":"General","textColor":"#FFFFFF"},{"bgColor":"#4D1B5E","label":"People Operations & AI","textColor":"#FFFFFF"},{"bgColor":"#E5C54F","label":"People & HR Compliance","textColor":"#FFFFFF"},{"bgColor":"#43143B","label":"People Experience","textColor":"#FFFFFF"}],"service_tag_types":[{"bgColor":"#FBEFC9","label":"Fixed project","textColor":"#26142E","value":"fixed"},{"bgColor":"","label":"Monthly retainer","textColor":"#FFFFFF","value":"retainer"}]}$mc$::jsonb where section_key = 'tags_config';
update public.cms_pages set draft_page_rows = $mc$[{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"80b5d5a0-ab68-495d-b6ab-9973b5230ebc","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"align":"left","answer":"Pay transparency consulting for companies of 10 to 2,000 people getting ready for the EU Pay Transparency Directive. I build job levels, pay bands, the pay-request process and the manager scripts, remote-first from Sweden, for teams anywhere.","body":"<p>Pay is the conversation plenty of growing companies postpone, right up until someone asks what their colleague earns. The EU Pay Transparency Directive turns that question into a right: pay ranges before the interview, pay criteria people can see, and a written answer within two months to anyone who asks how their pay compares with colleagues doing the same work, whatever the company's size.</p><p>We build the structure behind the answer: job levels, pay bands on gender-neutral criteria, the words your managers use, and a calm rollout. One set of foundations covers every country you hire in, with your employment lawyer signing off the local detail.</p>","color_label":"#6A010E","label":"Pay Transparency","title_lines":["<p><span style=\"color: rgb(106, 1, 14)\">Your salary bands live in the founder's head.</span></p>","<p><span style=\"color: rgb(106, 1, 14)\">Time for an exorcism.</span></p>"],"visual_image_alt":"Stacks of coins being arranged by hand, representing pay structures","visual_image_url":"https://mbxqjjmjywsxibttjrgr.supabase.co/storage/v1/object/public/media-library/gemini-generated-image-1lo5ka1lo5ka1lo5-1789074775583-l5p6gz.webp","visual_layout":"half_bleed","title_size":"compact","label_dot":true,"cta_label":"Book a free consultation","cta_url":"/#contact","answer_strip":true,"visual_badge_label":"Start with","visual_badge_title":"The Autopsy","visual_badge_text":"Pay Transparency Check · From €750"},"id":"31c5aaf5-4f53-40d8-885a-f1bc3345ffca","type":"hero"}]}],"id":"d8db3e98-1306-454a-a517-34118aa216f2"}],"id":"9b9dc4db-22c6-4202-acba-e628dffb60df","layout":{"alignment":"left","column_widths":[100],"columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false,"spaceTop":"lead","spaceBottom":"none"},"schema_version":3,"strip_title":"Hero"},{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"86449264-e56a-4b54-992d-c1d6066bb1c4","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"body":"<p></p>","eyebrow":"WHO IS THIS FOR","steps":[{"description":"<p>Founders and People leads at companies of 10 to 2,000 people who set salaries case by case and now need a structure they can explain out loud.</p>","title":""},{"description":"<p>Companies hiring across EU countries, where each country is writing its own version of the rules on its own timetable.</p>","title":""},{"description":"<p>Teams with a pay question already in the air: a new hire paid more than the people training them, a job advert that needs a range, or a request under the new information rights.</p>","title":""},{"description":"<p>On the first call, this is the thing I'm listening for: could your managers explain today why each person on their team earns what they earn.</p>","title":""}],"subtitle":"Built for the company that set pay one conversation at a time.","subtitle_handwritten":true,"title_lines":[],"step_style":"cards","subtitle_as_title":true,"last_step_as_note":true},"id":"a0277974-a893-445c-bef7-c176d2ab51e2","type":"process_steps"}]}],"id":"5781088a-9b2a-4080-8045-031d57ae5fcd"}],"id":"440315cf-2cbd-46c9-a64e-1b3252e18a3e","layout":{"alignment":"left","column_widths":[100],"columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false,"spaceTop":"full","spaceBottom":"near"},"schema_version":3,"strip_title":"How We Work"},{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"91f4ce22-c398-446c-adf7-901d2d87e935","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"__design":{"bgColor":"","borderRadius":0,"customCss":"","marginBottom":0,"marginLeft":0,"marginRight":0,"marginTop":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"visibility":{"desktop":true,"mobile":true}},"caption_position":"bottom-left","color_caption_bg":"","color_caption_text":"","color_description":"","color_eyebrow":"","color_title":"","description":"<p>Once the level, the range and the criteria are written down, a pay question becomes a two-minute conversation: here's your level, here's the range, here's why.</p><p>We build the version your managers can say out loud, and your staff can check for themselves.</p>","eyebrow":"What good looks like","floating_caption":"","image_alt":"Hands arranging stacks of coins into ordered piles","image_position":"left","image_shape":"default","image_url":"https://mbxqjjmjywsxibttjrgr.supabase.co/storage/v1/object/public/media-library/gemini-generated-image-1lo5ka1lo5ka1lo5-1789074775583-l5p6gz.webp","split_widths":[33,67],"title":"Pay people can explain, in a sentence.","title_lines":["<p>Pay people can explain, in a <span class=\"mc-accent\">sentence.</span></p>"],"panel_style":"pillar","pillar":"pay-transparency"},"id":"73b4b159-5a31-4412-b8b2-99f7ea924c44","type":"image_text"}]}],"id":"30c9b324-e101-4f42-a937-d5b3e238049b"}],"id":"ab843462-5ac8-402c-b813-14dec48f7168","layout":{"alignment":"left","columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":56,"paddingTop":56,"snapEnabled":false},"schema_version":3,"strip_title":"What Good Looks Like"},{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"e0abd0b6-7b66-489c-ad70-2875b7bf2b80","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"cards":[{"body":"Salaries set one negotiation at a time drift apart. Two people in the same role end up thousands of euros apart, the gap follows them into every raise, and the first person to compare payslips finds it before you do. The new rules give every employee the right to ask, and to get a written answer within two months.","icon":"lucide:CircleAlert","title":"The problem","variant":"dark"},{"body":"Three restructuring rounds across 36 countries, supporting roughly 500 employees, taught one lesson above all: people accept hard news far faster once it comes with a reason. Pay works the same way, and the explanation is the part that earns the trust.","icon":"lucide:Scale","title":"A background built for exactly this","variant":"glass"},{"body":"A social sciences background (anthropology, sociology, media and communication) means the pay structure accounts for how people feel about fairness, alongside what the spreadsheet says. The comms pack gets the same care as the bands.","icon":"lucide:GraduationCap","title":"Someone who understands the people behind the number","variant":"glass"}],"eyebrow":"Why The Magic Coffin","title_lines":["<p>Here's the problem, and here's the fix.</p>"],"marker_style":"bar"},"id":"f7eef0f7-28fd-4e60-bef1-0c68d0e34426","type":"boxed"}]}],"id":"0d662842-b66e-459c-a333-eb644d583221"}],"id":"54b36898-6682-4515-afed-94135788efc8","layout":{"alignment":"left","columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":56,"paddingTop":56,"snapEnabled":false,"spaceTop":"full","spaceBottom":"tight"},"schema_version":3,"strip_title":"Why The Magic Coffin"},{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"rs-30fbc0cd-8817-44bc-bae5-7c0d5887ebd0-service-cell0","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"card_text_align":"left","color_card_bg":"","color_card_description":"","color_card_title":"","color_carousel_btn_bg":"","color_carousel_btn_fg":"","color_cta_text":"","color_cta_time":"","color_deliverables_bg":"","color_deliverables_label":"","color_divider_from":"","color_divider_to":"","color_dot_active":"","color_dot_inactive":"","color_heading":"","color_heading_sub":"","color_label":"","color_meta_bg":"","color_meta_fg":"","color_note_border":"","color_primary":"","color_section_bg":"","color_subtitle":"","description":"<p>Every engagement starts with a free 30-minute call, where you get a straight answer including an honest read on fit.</p>","eyebrow":"Engagements","pillar_number":"Pillar 05","services":[{"deliverables":["Review of job adverts, interview scripts and application forms, with pay-history questions removed","Contract and handbook check for pay-secrecy clauses","Country-by-country summary of where the rules stand for each place you hire, dated","A template written reply for pay-information requests, with the two-month clock and the yearly reminder","Ranked gap list with a fixed price for closing each gap","One-hour walkthrough with the founders"],"description":"Before you build anything, you need to know how far you are from the rules in the countries you hire in. The Autopsy reviews your job adverts, interview scripts, contracts, handbook and current pay data against the Directive's duties, country by country, and makes the quick fixes on the spot. Done looks like: a ranked list of every gap, each with a fixed price to close it, and the quick fixes already made.","note":"It's the natural first step, and it often shows the job is smaller than it feels.","price":"Book a free consultation","subtitle":"Pay Transparency Check","tag":"Fixed project","tagType":"fixed","time":"From €750 · 1–2 weeks · ~12–15 hours","title":"The Autopsy","startHere":"start here"},{"deliverables":["One-page pay philosophy, agreed with the founders","Job levels for each role family, with plain-language level descriptions","Pay bands built on gender-neutral criteria, from your data plus a benchmark you choose","Placement of every current role in a level and band, with the reasons written down","Private pay-gap check for similar work, with a plan for any gap that needs closing","Ranges formatted for every job advert"],"description":"This is where the structure gets built: a one-page pay philosophy, job levels for each role family, and pay bands set on gender-neutral criteria (skills, effort, responsibility and working conditions), using your own data and a benchmark you choose. Done looks like: every role sitting in a level and a band with the reason written next to it, and a range ready for every job advert.","price":"Book a free consultation","subtitle":"Job Levels & Pay Bands","tag":"Fixed project","tagType":"fixed","time":"From €2,000 · 4–6 weeks · ~40–50 hours","title":"The Unmasking"},{"deliverables":["Rollout plan: who hears what, from whom, and when","All-hands script and a staff explainer in plain language","Pay-request process: who answers, from which data, within what time","Manager FAQ and scripts for the three awkward pay conversations","One 90-minute manager training session on pay conversations","Yearly reminder message for the right to pay information"],"description":"A pay structure works once people understand it. The Reckoning is the human half: the all-hands, the staff explainer, the process for answering pay requests, and the scripts your managers use when someone asks why they're paid what they're paid. Done looks like: every manager trained and able to answer the three awkward pay questions, and a pay-request process running with a named owner and a two-month deadline.","note":"For a wider manager programme, The Reckoning pairs with The Coven in Manager Enablement.","price":"Book a free consultation","subtitle":"Pay Communication & Manager Scripts","tag":"Fixed project","tagType":"fixed","time":"From €1,400 · 3–4 weeks · ~25–30 hours","title":"The Reckoning"},{"deliverables":["Pre-cycle manager briefing","Review-cycle comms for staff","Band check on every proposed increase","Support answering pay-information requests","Post-cycle report: what moved, what's outstanding, what needs a decision from you"],"description":"Pay transparency is a habit, and review season is where habits slip. The Ledger supports each pay review cycle: manager briefings, the comms, a check that every increase stays inside its band, and answers to the pay questions that arrive afterwards. Done looks like, every cycle: increases inside the bands, every manager briefed before the conversations start, and every pay request answered on time.","note":"For existing clients, The Ledger folds into a People Operations Resurrection retainer.","price":"Book a free consultation","subtitle":"Pay Season Partner","tag":"Per review cycle","tagType":"retainer","time":"From €600 per review cycle · ~10–14 hours per cycle","title":"The Ledger"}],"title":"What we can help with","card_layout":"grid","pillar":"pay-transparency"},"id":"ba278519-b239-489c-a7d2-e97c118fbc3d","type":"service"}]}],"id":"rs-30fbc0cd-8817-44bc-bae5-7c0d5887ebd0-service-col"}],"id":"30fbc0cd-8817-44bc-bae5-7c0d5887ebd0","layout":{"alignment":"left","column_widths":[100],"columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false,"spaceTop":"full","spaceBottom":"tight"},"schema_version":3,"strip_title":"Engagements"},{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"rs-30fbc0cd-8817-44bc-bae5-7c0d5887ebd0-faq-cell0","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"body":"<p></p>","eyebrow":"FAQ","items":[{"answer":"<p>Yes, most of it. Pay ranges before the interview, the ban on pay-history questions, visible pay criteria and the right to request pay information apply to employers of every size.</p><p>Countries can exempt companies under 50 people from sharing pay progression criteria, and gender pay-gap reporting starts at 100 employees.</p>","question":"Does the EU Pay Transparency Directive apply to small companies?"},{"answer":"<p>The EU gave member states until 7 June 2026 to turn the Pay Transparency Directive into national law, and most countries missed that deadline. Each one is writing its own version on its own timetable.</p><p>The Autopsy includes a dated, country-by-country summary for everywhere you hire, checked again before anything goes live.</p>","question":"When do the rules apply in my country?"},{"answer":"<p>The UK sits outside the Directive, and Sweden has asked the EU to renegotiate it.</p><p>Clear pay still helps you hire and keep people, and it gets you ready early if the rules arrive. We'll tell you plainly which parts matter for you.</p>","question":"We're in the UK or Sweden. Is this relevant?"},{"answer":"<p>It sits alongside legal advice. We build the structure, the words and the rollout; your employment lawyer signs off the local legal detail.</p><p>If you need a lawyer, we'll introduce one.</p>","question":"Is this legal advice?"},{"answer":"<p>It helps, and it's your choice. The Unmasking works from your own pay data plus a benchmark you pick: a paid tool, public salary surveys or recruiter data.</p><p>The method is written down either way, so you can explain every band.</p>","question":"Do we need pay-benchmarking software?"},{"answer":"<p>Then you found it first, which is the best place to be.</p><p>The Unmasking separates gaps your criteria explain from gaps that need closing, and gives you a plan and a budget for closing them over one or more pay cycles.</p>","question":"What if the check finds a pay gap?"},{"answer":"<p>It's a focused slice of it. <a href=\"/services/people-operations/\">People Operations</a> builds the systems and paperwork across the whole employee lifecycle. Pay Transparency covers one job end to end: levels, bands, the pay conversation and the rules behind them.</p><p>You can start here and move into People Operations later, or run both side by side.</p>","question":"Is Pay Transparency the same as People Operations?"}],"title_lines":["<p>Frequently asked questions</p>"],"subtitle":"If yours isn't here, that's what the free consultation is for."},"id":"c0f31a44-3194-43d2-be6f-d5e6552092d9","type":"faq"}]}],"id":"rs-30fbc0cd-8817-44bc-bae5-7c0d5887ebd0-faq-col"}],"id":"rs-30fbc0cd-8817-44bc-bae5-7c0d5887ebd0-faq","layout":{"alignment":"left","column_widths":[100],"columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false,"spaceTop":"full","spaceBottom":"tight"},"schema_version":3,"strip_title":"FAQ"},{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"bf8ab693-7bbf-4355-ae43-2dc32f65b847","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"categories":["People & HR Compliance"],"color_eyebrow":"","color_title":"","eyebrow":"Latest thinking","limit":3,"link_label":"All blogs & insights","title":"From the blog"},"id":"1faccb7a-1150-4142-bb9b-e3986951f026","type":"from_the_blog"}]}],"id":"20a9e771-9a2c-4f30-823b-894096ac6c44"}],"id":"b0774e15-1eab-4dcb-8182-42b9fe72cc60","layout":{"alignment":"left","column_widths":[100],"columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false,"spaceTop":"full","spaceBottom":"none"},"schema_version":3,"strip_title":"From the blog"},{"bg_color":"","column_layout":"custom","columns":[{"cell_direction":"vertical","cells":[{"id":"gap-contact-pay-transparency-cell","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"body":"Book a free 30-minute consultation. We'll identify your biggest vampire moment and tell you honestly whether we're the right fit to bury it.","button_text":"Book a free consultation","fields":[{"key":"name","label":"Your name","required":true,"type":"text","visible":true},{"key":"email","label":"Email address","required":true,"type":"email","visible":true},{"key":"company","label":"Company","required":false,"type":"text","visible":true},{"key":"message","label":"Tell us about your vampire moment","required":true,"type":"textarea","visible":true},{"key":"marketing","label":"Keep me updated with insights and articles","required":false,"type":"checkbox","visible":true}],"show_social":false,"success_body":"We aim to respond within 24 hours. Keep an eye out on your mailbox!","success_button":"Send another message","success_heading":"Thanks for making the first step!","title_lines":["<p>Not sure where to start?</p>","<p><span class=\"mc-accent\">Lift the lid first.</span></p>"],"stamp":"Lid off"},"id":"gap-contact-pay-transparency-widget","type":"contact"}]}],"id":"gap-contact-pay-transparency-col"}],"customCss":null,"id":"gap-contact-pay-transparency","layout":{"alignment":"left","columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false,"spaceTop":"full","spaceBottom":"full"},"schema_version":3,"scope":null,"strip_title":"Contact"}]$mc$::jsonb where slug = 'services/pay-transparency';
update public.cms_pages set draft_page_rows = $mc$[{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"bd756071-4ced-4972-9beb-346cc7a97135","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"align":"left","answer":"Internal communications consulting for companies of 50 to 2,000 people where comms is still a side job: an audit of what actually lands, a playbook for what to say and where, and a fractional communications lead to run it. Remote-first, from Sweden, for teams in any time zone.","body":"<p>Plenty of internal comms is noise the company calls important. Some of it earns the label. We help you cut through the rest by designing communication systems that reach people, move them, and mean something.</p><p>Whether you need a diagnosis, a full strategy, or an ongoing partner, we operate at the level your organisation needs.</p>","color_label":"#43143B","label":"Internal Communications","title_lines":["<p><span style=\"color: rgb(67, 20, 59)\">Your last town hall was a wake.</span></p>","<p><span style=\"color: rgb(67, 20, 59)\">The whole room went quiet.</span></p>"],"visual_image_alt":"A professional communicating clearly with colleagues, representing effective internal communications","visual_image_url":"https://mbxqjjmjywsxibttjrgr.supabase.co/storage/v1/object/public/editor-images/gallery/1788710695872-b6b7dkl4w7u.jpg","visual_layout":"half_bleed","title_size":"compact","label_dot":true,"cta_label":"Book a free consultation","cta_url":"/#contact","answer_strip":true,"visual_badge_label":"Start with","visual_badge_title":"The Autopsy","visual_badge_text":"Internal Communications Audit · From €900"},"id":"12a0b887-0670-4934-8ca8-ee3f755481e5","type":"hero"}]}],"id":"e9092e21-4c26-4ab8-a423-2f9bdf747a57"}],"id":"2303aaa6-e04e-448f-830d-e3df2c8ddff0","layout":{"alignment":"left","column_widths":[100],"columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false,"spaceTop":"lead","spaceBottom":"none"},"schema_version":3,"strip_title":"Hero"},{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"8b0bf13f-7f40-4042-bb57-ef57dbe59e0e","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"body":"<p></p>","eyebrow":"Who this is for","steps":[{"description":"<p>Led by someone who cares about the mission and knows better than to expect employees to feel the same way about a paycheck. People show up to learn something, earn something, or simply be respected, heard and motivated to succeed. Every one of those reasons is fair. Roughly 50 up to 2,000 people in, where internal comms is still a side task someone picks up between other jobs.</p>","title":""},{"description":"<p>Multi-location or hybrid and remote, where messages visibly land differently depending on which office, or time zone, people sit in.</p>","title":""},{"description":"<p>Growing fast enough that last year's comms habits, a Slack channel, an occasional email, are starting to visibly crack: town halls feel flat, and people say they hear big news from LinkedIn before they hear it internally.</p>","title":""},{"description":"<p>On the first call, this is the thing I'm listening for: was the employee part of the decision, or just the paperwork after it.</p>","title":""}],"subtitle":"Built for the scale-up that has outgrown ad hoc updates and is still waiting on its first comms hire.","subtitle_handwritten":true,"title_lines":[],"step_style":"cards","subtitle_as_title":true,"last_step_as_note":true},"id":"b43b2f3b-45f1-4f85-8c51-bad1937d55cb","type":"process_steps"}]}],"id":"b958761c-c5c7-4f50-a3f2-1883b69aeb3b"}],"id":"ec69b0b6-8797-41fe-8008-49dca00072e5","layout":{"alignment":"left","column_widths":[100],"columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false,"spaceTop":"full","spaceBottom":"near"},"schema_version":3,"strip_title":"Who this is for"},{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"f5fc6576-b8e4-47ee-a16c-74543bab9fc9","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"__design":{"bgColor":"","borderRadius":0,"customCss":"","marginBottom":0,"marginLeft":0,"marginRight":0,"marginTop":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"visibility":{"desktop":true,"mobile":true}},"caption_position":"bottom-left","color_caption_bg":"","color_caption_text":"","color_description":"","color_eyebrow":"","color_title":"","description":"<p>Picture the room this actually happens in: a dark conference table, one screen, a leader about to say something that matters. Whether that moment lands or dies in the room depends less on the words than on everything built around them, the channel, the timing, the trust already banked.</p><p>That is the work: the system around the town hall deck that makes the message land.</p>","eyebrow":"What good looks like","floating_caption":"","image_alt":"An uncluttered, organised workspace representing clear internal communication","image_position":"left","image_shape":"default","image_url":"https://mbxqjjmjywsxibttjrgr.supabase.co/storage/v1/object/public/media-library/internal-comms-1788701614483-of4o11.jpg","split_widths":[33,67],"title":"A message that survives the trip from you to them.","title_lines":["<p>A message that survives the trip from <span class=\"mc-accent\">you to them.</span></p>"],"panel_style":"pillar","pillar":"internal-communications"},"id":"41b7c119-2b17-4bd3-b34f-fa7630862ab6","type":"image_text"}]}],"id":"03bce203-8cc6-442b-8010-1f73b30d6820"}],"id":"1b5549be-1239-4300-9e83-d81b5e0800ef","layout":{"alignment":"left","columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":56,"paddingTop":56,"snapEnabled":false},"schema_version":3,"scope":null,"strip_title":"What Good Looks Like"},{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"1385e1fb-d044-47ad-a2c3-e9abe5239777","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"cards":[{"body":"A message goes out. Half the company reads it three days late, from a manager who found out at the same time everyone else did. The town hall becomes background noise instead of real news, and the next announcement lands to a room that has already stopped listening. By the next announcement you are paying twice: once to send it, and again to convince a room that has learned to skim.","icon":"lucide:CircleAlert","title":"The problem","variant":"dark"},{"body":"Years spent working across different departments, seeing first-hand how the same announcement lands completely differently in engineering than it does in sales. A social sciences background (anthropology, sociology, media and communication) turned into the actual skill of reading a room before it reacts.","icon":"lucide:GraduationCap","title":"A background built for this exact problem","variant":"glass"},{"body":"Three redundancy rounds, run across 36 countries, taught real lessons about how people hear hard news, and what helps them trust it. That judgement sits behind every message this pillar writes, from the first line of a script to the tone of the follow-up email.","icon":"lucide:BadgeCheck","title":"Someone who's watched news land, badly and well","variant":"glass"}],"eyebrow":"Why The Magic Coffin","title_lines":["<p>Here's the problem, and here's the fix.</p>"],"marker_style":"bar"},"id":"9868146e-3a06-4711-8d15-3503b859f3ec","type":"boxed"}]}],"id":"4fc71d11-7bc3-4d2d-9198-8e7ec8689d3a"}],"id":"4d8785d3-96c7-44d6-9d8e-7cbaa21d68b5","layout":{"alignment":"left","columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":56,"paddingTop":56,"snapEnabled":false,"spaceTop":"full","spaceBottom":"tight"},"schema_version":3,"scope":null,"strip_title":"Why The Magic Coffin"},{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"rs-58a4533e-9944-46f0-84d8-7909509d8aa5-service-cell0","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"color_card_bg":"","color_card_description":"","color_card_title":"","color_carousel_btn_bg":"","color_carousel_btn_fg":"","color_cta_text":"","color_cta_time":"","color_deliverables_bg":"","color_deliverables_label":"","color_divider_from":"","color_divider_to":"","color_dot_active":"","color_dot_inactive":"","color_heading":"","color_heading_sub":"","color_label":"","color_meta_bg":"","color_meta_fg":"","color_note_border":"","color_primary":"","color_section_bg":"","color_subtitle":"","description":"<p>Every engagement starts with a free 30-minute call, where you get a straight answer including an honest read on fit.</p>","eyebrow":"Engagements","pillar_number":"Pillar 01","services":[{"deliverables":["Stakeholder interviews across 3–5 levels of the organisation","Full audit of your channels, cadence, tone and governance","Identification of your top \"vampire moments\": where comms is draining energy","Written findings report (15–25 pages): clear, direct, no corporate fog","Live presentation and Q&A walkthrough (90 minutes)","Prioritised 30/60/90-day action roadmap"],"description":"Something is off. Messages are landing flat. Town halls feel like theatre. Employees know less about the company than the LinkedIn page does. The Autopsy is where we lift the lid: assess what's working, what's dead, and what's actively draining your culture. You get a sharp, honest report and a prioritised action roadmap. Done looks like: a written map of where messages break down between you and the people meant to receive them, with your top vampire moments ranked, and a 30/60/90 roadmap your leadership team can act on the same week.","note":"The Autopsy is the natural starting point for most clients, and it almost always reveals enough to warrant The Burial. Consider it an investment that pays for itself.","price":"Book your Autopsy","subtitle":"Internal Communications Audit","tag":"Fixed project","tagType":"fixed","time":"From €900 · 2–3 weeks · ~15–20 hours","title":"The Autopsy","startHere":"start here"},{"deliverables":["Extended discovery: cross-level stakeholder interviews + employee pulse survey","Leadership communication style assessment","Channel architecture design: what lives where, for whom, with what purpose","Messaging framework and internal tone of voice guidelines","Content calendar structure and governance model","The Playbook: a practical, branded document covering the full system","3–5 ready-to-use templates (all-hands agenda, newsletter format, announcement, manager cascade)","Measurement framework: which metrics matter, how to track them, what good looks like","Full leadership presentation + 90-minute team training session","30-day post-delivery check-in call included"],"description":"You know the problem. Now it's time to bury it properly and build something that lasts. The Burial is a full end-to-end Internal Comms transformation: we design your channel architecture, messaging framework, governance model and content calendar, then hand you a practical playbook your team can open and use on Monday morning: a working system, ready to run. Done looks like: a channel architecture, a messaging framework and a content calendar live in your own tools, with your team running an all-hands, a newsletter and a cascade from the templates, unaided, before handover ends.","price":"Book a free consultation","subtitle":"Internal Communications Strategy & Playbook","tag":"Fixed project","tagType":"fixed","time":"From €2,250 · 5–7 weeks · ~40–50 hours","title":"The Burial"},{"deliverables":["Monthly strategy session with your People or Comms lead","Comms calendar planning and prioritisation","Writing and editing: all-hands content, leadership messages, newsletters, announcements","Crisis and sensitive comms advisory (restructures, cultural moments, leadership changes)","Intranet content management and optimisation","Engagement campaign ideation and execution","Monthly metrics report with engagement data and recommendations"],"description":"You need the judgement of a Head of Internal Comms, on demand, for a couple of days a month. The Resurrection puts a senior comms partner in your corner every month: writing, advising, measuring and iterating alongside your People team. Whether it's navigating a restructure, launching a new initiative or simply keeping the heartbeat of your organisation steady, we hold the pen. Done looks like, every month: the comms calendar planned, the month's leadership messages and announcements drafted, and a metrics report with engagement data and the recommendations that follow from it.","note":"The 3-month minimum is a commitment to your results: real cultural change takes longer than four weeks, and we're building something that lasts.","price":"Book a free consultation","subtitle":"Fractional Internal Communications Lead","tag":"Monthly Retainer","tagType":"retainer","time":"From €900 a month · Minimum 3-month commitment · ~14–20 hrs/mo","title":"The Resurrection"}],"title":"What we can help with","card_layout":"grid","pillar":"internal-communications"},"id":"0dc3c9bb-5845-43b7-bb8f-62bb10d76d3b","type":"service"}]}],"id":"rs-58a4533e-9944-46f0-84d8-7909509d8aa5-service-col"}],"id":"58a4533e-9944-46f0-84d8-7909509d8aa5","layout":{"alignment":"left","column_widths":[100],"columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false,"spaceTop":"full","spaceBottom":"tight"},"schema_version":3,"strip_title":"Engagements"},{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"rs-58a4533e-9944-46f0-84d8-7909509d8aa5-faq-cell0","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"eyebrow":"FAQ","items":[{"answer":"<p>It depends on your trajectory.</p><p>The Autopsy and Burial are designed to leave you with a system your team can run independently.</p><p>The fractional retainer exists for the common middle ground: senior comms judgement on a regular basis, at a level still short of justifying a full-time hire.</p>","question":"Will this replace our need for a comms hire eventually?"},{"answer":"<p>Both, depending on the tier.</p><p>The Autopsy diagnoses and recommends.</p><p>The Burial and the fractional retainer both include hands-on drafting: scripts, announcements, cascade materials, real material your team can use directly, alongside the strategy itself.</p><p>For a pay rollout, the all-hands script, staff explainer and manager pay scripts sit with <a href=\"/services/pay-transparency\">Pay Transparency</a>.</p>","question":"Do you write the actual messages, or just advise on strategy?"},{"answer":"<p>It's handled the way the report itself is handled: directly, plainly, and privately with you before anything reaches a wider audience.</p><p>Individual interviewees stay unquoted by name throughout.</p>","question":"What if the audit turns up something politically sensitive?"},{"answer":"<p>Yes. It's often exactly when the gaps in a comms system get exposed.</p><p>If the crisis leans more HR than comms, The Vigil under <a href=\"/services/fractional-hrbp\">Fractional HRBP</a> is the better fit. Ask on the discovery call and we'll help you tell which.</p>","question":"Can this run during an active reorg or comms crisis?"},{"answer":"<p>The Autopsy runs two to three weeks: around 15 to 20 hours of your team's time across interviews and the findings walkthrough.</p><p>The Burial, the full strategy and playbook, runs five to seven weeks.</p>","question":"How long does an internal communications audit take?"},{"answer":"<p>A written findings report you can hand straight to your leadership team.</p><p>For the Burial, also a practical playbook with ready-to-use templates: an all-hands agenda, a newsletter format, an announcement structure, a manager cascade script.</p><p>Real things your team opens on a Monday morning and puts to work, rather than a deck that sits in a folder.</p>","question":"What's the actual deliverable, not just the process?"},{"answer":"<p>Where messages break down between you and the people meant to receive them: channel overload, manager cascade failures, one-way broadcasts standing in for real two-way communication.</p><p>And the specific moments people quietly stop listening. Interviews surface this, in a way a survey template rarely can.</p><p>When the break sits with managers, <a href=\"/services/manager-enablement\">Manager Enablement</a> gives them a briefing template for passing news on within 24 hours, and a place to practise it.</p>","question":"What does an internal communications audit actually look at?"}],"title_lines":["<p>Frequently asked questions</p>"],"subtitle":"If yours isn't here, that's what the free consultation is for."},"id":"ed7dfcec-a784-4a81-993b-269e70f41a5f","type":"faq"}]}],"id":"rs-58a4533e-9944-46f0-84d8-7909509d8aa5-faq-col"}],"id":"rs-58a4533e-9944-46f0-84d8-7909509d8aa5-faq","layout":{"alignment":"left","column_widths":[100],"columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false,"spaceTop":"full","spaceBottom":"tight"},"schema_version":3,"strip_title":"FAQ"},{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"906277f1-4435-42f9-b9aa-ed19f0334433","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"categories":["People Operations & AI","People Experience","People & HR Compliance"],"color_eyebrow":"","color_title":"","eyebrow":"Latest thinking","limit":3,"link_label":"All blogs & insights","title":"From the blog"},"id":"6f12910c-7165-439c-a89d-b9ec0983cf06","type":"from_the_blog"}]}],"id":"b2f51008-f878-4c45-8b35-d4bf6003f25e"}],"id":"7c5eb13f-443a-440b-b36c-e08a13e49448","layout":{"alignment":"left","column_widths":[100],"columns":1,"fullWidth":false,"heightMode":"auto","marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false,"spaceTop":"full","spaceBottom":"none"},"schema_version":3,"strip_title":"From the blog"},{"bg_color":"","column_layout":"custom","columns":[{"cell_direction":"vertical","cells":[{"id":"gap-contact-internal-communications-cell","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"body":"Book a free 30-minute consultation. We'll identify your biggest vampire moment and tell you honestly whether we're the right fit to bury it.","button_text":"Book a free consultation","fields":[{"key":"name","label":"Your name","required":true,"type":"text","visible":true},{"key":"email","label":"Email address","required":true,"type":"email","visible":true},{"key":"company","label":"Company","required":false,"type":"text","visible":true},{"key":"message","label":"Tell us about your vampire moment","required":true,"type":"textarea","visible":true},{"key":"marketing","label":"Keep me updated with insights and articles","required":false,"type":"checkbox","visible":true}],"show_social":false,"success_body":"We aim to respond within 24 hours. Keep an eye out on your mailbox!","success_button":"Send another message","success_heading":"Thanks for making the first step!","title_lines":["<p>Not sure where to start?</p>","<p><span class=\"mc-accent\">Lift the lid first.</span></p>"],"stamp":"Lid off"},"id":"gap-contact-internal-communications-widget","type":"contact"}]}],"id":"gap-contact-internal-communications-col"}],"customCss":null,"id":"gap-contact-internal-communications","layout":{"alignment":"left","columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false,"spaceTop":"full","spaceBottom":"full"},"schema_version":3,"scope":null,"strip_title":"Contact"}]$mc$::jsonb where slug = 'services/internal-communications';
update public.cms_pages set draft_page_rows = $mc$[{"bg_color":"","column_layout":"custom","columns":[{"cell_direction":"vertical","cells":[{"id":"121cad9d-a0d5-4a2b-9d11-ff175921da37","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"body":"<p><strong>1. Who we are.</strong> The Magic Coffin (the “Company”, “we”, “us”) is the data controller for personal data collected through this website. You can reach us at <a href=\"mailto:hello@themagiccoffin.com\">hello@themagiccoffin.com</a>.</p><p><strong>2. What data we collect.</strong> We collect data you give us directly (e.g. your name, email, company, message) when you book a call through our Google Calendar booking page, and limited technical data (IP address, device, browser) collected automatically for analytics and security.</p><p><strong>3. Why we use it (legal bases under the GDPR).</strong> We process your data to (a) respond to your enquiry: necessary for steps prior to entering a contract; (b) arrange and hold the calls you book; (c) measure traffic and improve our services: based on our legitimate interest in running the site, balanced against your privacy.</p><p><strong>4. Cookies.</strong> We use a small number of strictly necessary cookies and, with your consent, analytics cookies. You can manage or revoke consent at any time from the cookie banner.</p><p><strong>5. Sharing.</strong> We share data only with processors that help us run the service (hosting, appointment booking through Google Calendar, analytics). All processors are bound by data-processing agreements and process data inside the EU/EEA or under approved transfer mechanisms.</p><p><strong>6. Retention.</strong> We keep contact submissions for as long as needed to handle your request and up to 24 months thereafter. Analytics logs are kept for 14 months.</p><p><strong>7. Your rights.</strong> You have the right to access, rectify, erase, restrict, or port your data, to object to processing, and to withdraw consent. To exercise any of these rights write to <a href=\"mailto:hello@themagiccoffin.com\">hello@themagiccoffin.com</a>. You also have the right to lodge a complaint with your local data-protection authority.</p><p><strong>8. Security.</strong> We use TLS in transit, encryption at rest, role-based access controls, and regular backups. No system is 100% secure, but we follow industry best practice.</p><p><strong>9. Changes.</strong> We may update this policy from time to time. Material changes will be announced on this page with a new “Last updated” date.</p>","cta_label":"","cta_url":"","eyebrow":"Legal","note":"","subtitle":"Last updated: 19 Apr 2026","subtitle_color":"","title_lines":["<p>Privacy Policy</p>"],"panel_style":"glass"},"id":"af427f77-ef81-466d-a05a-244a48019ed4","type":"text"}]}],"id":"949d2bb2-c9a9-46b5-b9e5-260af2681e25"}],"customCss":null,"id":"2a967f32-8bcb-42d7-91f9-666142b686d3","layout":{"alignment":"left","snapEnabled":false},"schema_version":3,"scope":null,"strip_title":"Privacy Policy"}]$mc$::jsonb where slug = 'privacy-policy';
update public.cms_pages set draft_page_rows = $mc$[{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"f9ad46da-7779-48d2-929c-3b5a0cac0797","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"align":"left","answer":"Employee experience consulting for growing companies: onboarding that lasts past week one, engagement you can measure, and an employee journey designed on purpose instead of by accident. Fractional, remote-first from Sweden, anywhere your people are.","body":"<p>The modern workplace is haunted by zombie journeys: onboarding processes that disappear after week one, surveys that end up as one slide in a deck, and employees who feel invisible by month three.</p><p>We design experiences that treat your people like the humans they are, from the moment they sign the offer to the moment they hand in their laptop.</p>","color_label":"#002B67","label":"Employee Experience","title_lines":["<p><span style=\"color: rgb(0, 43, 103)\">They already quit. Their badge</span></p>","<p><span style=\"color: rgb(0, 43, 103)\">is running a few weeks behind.</span></p>"],"visual_image_alt":"Colleagues in a professional workplace setting, reflecting positive employee experience","visual_image_url":"https://mbxqjjmjywsxibttjrgr.supabase.co/storage/v1/object/public/media-library/pexels-edmond-dantes-8069014-1788710964440-pjkn9m.jpg","visual_layout":"half_bleed","title_size":"compact","label_dot":true,"cta_label":"Book a free consultation","cta_url":"/#contact","answer_strip":true,"visual_badge_label":"Start with","visual_badge_title":"The Autopsy","visual_badge_text":"Employee Experience Audit · From €900"},"id":"8272ea46-8f30-4bdf-b7ec-2a2e100b5f6c","type":"hero"}]}],"id":"0b7aa6d9-da2c-4481-a0bd-01aa617834bd"}],"id":"c6cf4294-e1ef-4cd5-8ede-e302769be415","layout":{"alignment":"left","column_widths":[100],"columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false,"spaceTop":"lead","spaceBottom":"none"},"schema_version":3,"strip_title":"Hero"},{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"b6fe3308-a55f-4ed7-9430-448d78ccc40d","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"body":"<p></p>","eyebrow":"Who this is for","steps":[{"description":"<p>For founders and leaders who care about the mission enough to protect their people from having to care about it the same way. Employees are there to learn something, earn something, or simply be respected, heard and motivated to succeed, and every one of those reasons is enough. Roughly 50 up to 2,000 people in, hiring fast enough that onboarding has started to visibly vary by team or manager.</p>","title":""},{"description":"<p>Rising attrition or flat eNPS with no clear read on why: the anecdotal explanations, comp, burnout, don't fully add up against what people actually say when asked directly.</p>","title":""},{"description":"<p>A People team that owns EX in name but not in practice: HR is absorbed by admin and hiring, and the actual experience design work keeps getting pushed to next quarter.</p>","title":""},{"description":"<p>On the first call, this is the thing I'm listening for: was the employee part of the decision, or just the paperwork after it.</p>","title":""}],"subtitle":"Built for the scale-up where growth has started to outpace the experience.","subtitle_handwritten":true,"title_lines":[],"step_style":"cards","subtitle_as_title":true,"last_step_as_note":true},"id":"46ac98e3-59cd-4687-a9a3-18772350d01c","type":"process_steps"}]}],"id":"bdeaa766-f62e-4299-861d-081a0036de61"}],"id":"e6870bc3-4d06-4431-977a-bc3faeda6066","layout":{"alignment":"left","column_widths":[100],"columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false,"spaceTop":"full","spaceBottom":"near"},"schema_version":3,"strip_title":"Who this is for"},{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"d7389d39-54ef-48d3-8f38-1e5030cc88bd","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"__design":{"bgColor":"","borderRadius":0,"customCss":"","marginBottom":0,"marginLeft":0,"marginRight":0,"marginTop":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"visibility":{"desktop":true,"mobile":true}},"caption_position":"bottom-left","color_caption_bg":"","color_caption_text":"","color_description":"","color_eyebrow":"","color_title":"","description":"<p>A good employee experience runs deeper than a wellness Friday. It is a series of moments, onboarding, a first difficult month, a promotion that should have happened sooner, each one designed rather than left to whoever happens to be free that week.</p><p>Design the moments and the retention numbers tend to sort themselves out.</p>","eyebrow":"What good looks like","floating_caption":"","image_alt":"Two colleagues walking together down a hallway, representing supported employee experience","image_position":"right","image_shape":"default","image_url":"https://mbxqjjmjywsxibttjrgr.supabase.co/storage/v1/object/public/media-library/employee-experience-1788701848443-7vyf1d.jpg","split_widths":[67,33],"title":"Nobody walks that hallway alone by accident.","title_lines":["<p>Nobody walks that hallway alone by <span class=\"mc-accent\">accident.</span></p>"],"panel_style":"pillar","pillar":"employee-experience"},"id":"1e977110-c5ae-44ed-b28b-44b0e9be6b0b","type":"image_text"}]}],"id":"982193b9-e7f1-404a-a44d-b95903674113"}],"id":"88412aa0-f8c3-4eee-ac28-5965d4a0c566","layout":{"alignment":"left","columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":56,"paddingTop":56,"snapEnabled":false},"schema_version":3,"scope":null,"strip_title":"What Good Looks Like"},{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"5966bb5d-82e8-41a8-a443-3863e9465883","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"cards":[{"body":"Onboarding ends after week one. The engagement survey produces a number, gets filed and gets forgotten. People quietly check out long before they hand in their notice. A recognition programme launches with real energy, and shows up in exit interviews six months later as the thing that quietly stopped. Attrition tends to get explained by pay. The leavers themselves tend to describe a moment instead.","icon":"lucide:CircleAlert","title":"The problem","variant":"dark"},{"body":"A social sciences background (anthropology, sociology, media and communication) built specifically around understanding how people really experience their work, beyond whatever a survey happens to score.","icon":"lucide:GraduationCap","title":"A background built for understanding the employee","variant":"glass"},{"body":"Feeling heard and feeling cared for carry as much weight here as any audit or roadmap. A global eNPS programme that held over 70% participation through 2025 happened because people trusted the process enough to keep answering.","icon":"lucide:HeartHandshake","title":"Employee experience is the actual work","variant":"glass"}],"eyebrow":"Why The Magic Coffin","title_lines":["<p>Here's the problem, and here's the fix.</p>"],"marker_style":"bar"},"id":"a08c5b5b-ff6c-46bf-a740-144d22993c50","type":"boxed"}]}],"id":"b022794b-a620-4f98-b003-5453b70a6e46"}],"id":"82f606c6-cd91-46a2-aa55-012c0a553773","layout":{"alignment":"left","columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":56,"paddingTop":56,"snapEnabled":false,"spaceTop":"full","spaceBottom":"tight"},"schema_version":3,"scope":null,"strip_title":"Why The Magic Coffin"},{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"rs-caa96fb3-bc17-44fb-acd0-9fecf9b6deeb-service-cell0","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"color_card_bg":"","color_card_description":"","color_card_title":"","color_cta_text":"","color_cta_time":"","color_deliverables_bg":"","color_deliverables_label":"","color_heading":"","color_heading_sub":"","color_label":"","color_meta_bg":"","color_meta_fg":"","color_note_border":"","color_section_bg":"","color_subtitle":"","description":"<p>Every engagement starts with a free 30-minute call, where you get a straight answer including an honest read on fit.</p>","eyebrow":"Engagements","pillar_number":"Pillar 02","services":[{"deliverables":["Interviews with employees across tenure: new joiners, mid-tenure, long-tenured","Full lifecycle touchpoint review: attraction through offboarding","Analysis of existing data: turnover patterns, exit themes, eNPS trends","A one-page visual Employee Journey Map: a powerful standalone deliverable","Identification of your top 3 vampire moments draining the experience","Prioritised recommendations report with quick wins and longer-term fixes","60-minute live presentation and Q&A"],"description":"Before you can fix the experience, you need to know where it's bleeding. We map the full employee lifecycle, from first impression to final goodbye, and identify the moments where energy, trust and engagement are being quietly drained. You'll walk away with a visual journey map, a clear-eyed assessment of your vampire moments, and a concrete list of what to fix first. Done looks like: a one-page journey map of your full employee lifecycle, your top three vampire moments named with evidence from your own people, and a prioritised list separating quick wins from the longer fixes.","note":"The Autopsy is the natural starting point for most clients, and it almost always reveals enough to warrant either an Awakening or a Séance. Consider it an investment that pays for itself.","price":"Book a free consultation","subtitle":"Employee Experience Audit","tag":"Fixed project","tagType":"fixed","time":"From €900 · 2 weeks · ~14–18 hours","title":"The Autopsy","startHere":"start here"},{"deliverables":["Discovery interviews: hiring managers, recent joiners (positive and negative experiences), People team","Audit of all existing onboarding materials","Full journey design: defined outcomes at Day 1, Week 1, Month 1, Month 3","Content architecture: what content, in what format, delivered how and by whom","Buddy Programme design (structure, matching logic, guide materials)","LMS course structure and content brief if applicable","Manager onboarding guide: what good looks like at each stage","Branded templates and materials (video or imagery production included)","Full handover session + 60-minute manager training"],"description":"Bad onboarding is one of the most expensive things a company can do. New hires decide whether they've made the right choice within the first 90 days, and plenty of onboarding programmes check out at the end of week one. We design the full journey from offer acceptance to settled, contributing team member: the moments, the content, the manager guides, the buddy framework, the LMS structure, all of it, built for humans rather than checklists. Done looks like: a full onboarding journey live from offer acceptance to month three, with defined outcomes at day one, week one, month one and month three, plus a manager guide and branded materials your team uses directly.","price":"Book a free consultation","subtitle":"Onboarding Experience Design","tag":"Fixed project","tagType":"fixed","time":"From €2,000 · 4–6 weeks · ~35–45 hours","title":"The Awakening"},{"deliverables":["Survey design: question selection, scale choices, demographic cuts, eNPS architecture","Full communications plan: pre-launch, during fieldwork, post-results","Survey setup, testing and launch management","Real-time participation monitoring with targeted nudge communications","Full results analysis: scores, department cuts, demographic patterns, open text themes","Visual results presentation for leadership: clear, honest, actionable","2–3 hour results workshop with leadership: what do we actually do about this?","90-day action plan with owners, timelines and success metrics"],"description":"Plenty of companies buy a survey tool, send the survey, look at a number, and call it a day. The number sits in a deck. Six months later, the same problems are still there and employees are more cynical too, because they filled in a survey and watched everything stay the same. We design the survey, run it, analyse the results and, most importantly, lead the action planning that turns a number into a movement. Done looks like: a survey designed, launched and analysed with participation reported openly, and a 90-day action plan leaving the workshop with owners, timelines and success measures attached to each item.","price":"Book a free consultation","subtitle":"Engagement Survey Design & Action Planning","tag":"Fixed project","tagType":"fixed","time":"From €1,400 · 4–5 weeks · ~25–30 hours","title":"The Séance"},{"deliverables":["Monthly strategy session with your People lead","Ongoing onboarding and offboarding process maintenance and improvement","eNPS and pulse survey management, analysis and reporting","ERG support, facilitation and content production","Recognition programme management and iteration","Ad hoc culture and engagement campaign design and execution","Structured exit interviews with departing employees: conducted with empathy, minus the HR theatre","Monthly exit insights report: themes, patterns, and honest recommendations for what's driving people out the door"],"description":"Employee experience is a practice, kept up month after month. The Resurrection puts an experienced EX partner at your side every month: maintaining, iterating and improving the experiences that keep your people engaged, growing and staying. Particularly powerful for scale-ups hiring fast, where the employee experience can collapse under growth pressure while everyone's too busy shipping to notice. Done looks like, every month: eNPS and pulse surveys run and reported, onboarding and offboarding kept current, exit interviews held, and a monthly insights report naming what is driving people out.","note":"The 3-month minimum is a commitment to your results: real cultural change takes longer than four weeks, and we're building something that lasts.","price":"Book a free consultation","subtitle":"Fractional Employee Experience Partner","tag":"Monthly retainer","tagType":"retainer","time":"From €900 a month · Minimum 3-month commitment · ~14–20 hrs/mo","title":"The Resurrection"}],"title":"What we can help with","card_layout":"grid","pillar":"employee-experience"},"id":"45b6393e-e298-44d7-8555-bb5855884652","type":"service"}]}],"id":"rs-caa96fb3-bc17-44fb-acd0-9fecf9b6deeb-service-col"}],"id":"caa96fb3-bc17-44fb-acd0-9fecf9b6deeb","layout":{"alignment":"left","column_widths":[100],"columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false,"spaceTop":"full","spaceBottom":"tight"},"schema_version":3,"strip_title":"Engagements"},{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"rs-caa96fb3-bc17-44fb-acd0-9fecf9b6deeb-faq-cell0","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"eyebrow":"FAQ","items":[{"answer":"<p>Plenty of engagement survey tools measure and stop there, short of diagnosing or fixing anything.</p><p>The Autopsy tells you specifically where the experience breaks and why, inside your own organisation, rather than a benchmark score against companies you've barely heard of.</p>","question":"How is this different from just running an engagement survey ourselves?"},{"answer":"<p>Individual sentiment stays anonymised by default in every written deliverable, kept untraceable to any single name.</p><p>People tend to say more when they trust that.</p>","question":"Will employees know their interview answers are attributed to them?"},{"answer":"<p>That actually strengthens the case for starting one, and the Autopsy notes the gap itself as a finding.</p><p>The audit draws on whatever data exists, plus direct interviews, either way.</p>","question":"What if we don't have exit-interview data to analyse?"},{"answer":"<p>Alongside, usually.</p><p>The Séance adds diagnosis and a real action loop on top of whatever tool sends the survey. Sending the survey was always the easy part; acting on what it finds is where the real work sits.</p>","question":"Does this replace or work alongside our existing engagement survey tool?"},{"answer":"<p>The onboarding programme that quietly fades out after week one.</p><p>The engagement survey that produces a number, goes into a slide, and gets filed away for good.</p><p>Small, undramatic moments that add up to someone quietly disengaging by month three.</p>","question":"What's a vampire moment in an employee's journey, concretely?"},{"answer":"<p>The Awakening runs four to six weeks.</p><p>It covers the full journey from offer acceptance to a settled, contributing team member: content, manager guides, a buddy programme, and an LMS structure where you use one.</p><p>Where the managers doing the onboarding are new to managing themselves, <a href=\"/services/manager-enablement\">Manager Enablement</a> adds a full manager kit, small practice cohorts and one-to-one coaching.</p>","question":"How long does onboarding redesign take?"},{"answer":"<p>Yes, as part of the Awakening.</p><p>The actual path from offer acceptance to a settled, contributing team member, mapped against what's really happening inside your organisation, built fresh each time rather than pulled from a generic template.</p>","question":"Do you build an employee journey map?"}],"title_lines":["<p>Frequently asked questions</p>"],"subtitle":"If yours isn't here, that's what the free consultation is for."},"id":"0d2b32bc-cdf6-4ede-a774-b918f2370605","type":"faq"}]}],"id":"rs-caa96fb3-bc17-44fb-acd0-9fecf9b6deeb-faq-col"}],"id":"rs-caa96fb3-bc17-44fb-acd0-9fecf9b6deeb-faq","layout":{"alignment":"left","column_widths":[100],"columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false,"spaceTop":"full","spaceBottom":"tight"},"schema_version":3,"strip_title":"FAQ"},{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"a3a14402-2533-4dac-901f-bc70de8775ee","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"categories":["People Experience"],"color_eyebrow":"","color_title":"","eyebrow":"Latest thinking","limit":3,"link_label":"All blogs & insights","title":"From the blog"},"id":"0e4d26ad-1c8e-42f1-a0a7-c66bcd7d1e77","type":"from_the_blog"}]}],"id":"8400ab61-c088-4908-9b4d-f91486d6b007"}],"id":"448f9a11-e38f-4061-9609-1b101fd2017c","layout":{"alignment":"left","column_widths":[100],"columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false,"spaceTop":"full","spaceBottom":"none"},"schema_version":3,"strip_title":"From the blog"},{"bg_color":"","column_layout":"custom","columns":[{"cell_direction":"vertical","cells":[{"id":"gap-contact-employee-experience-cell","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"body":"Book a free 30-minute consultation. We'll identify your biggest vampire moment and tell you honestly whether we're the right fit to bury it.","button_text":"Book a free consultation","fields":[{"key":"name","label":"Your name","required":true,"type":"text","visible":true},{"key":"email","label":"Email address","required":true,"type":"email","visible":true},{"key":"company","label":"Company","required":false,"type":"text","visible":true},{"key":"message","label":"Tell us about your vampire moment","required":true,"type":"textarea","visible":true},{"key":"marketing","label":"Keep me updated with insights and articles","required":false,"type":"checkbox","visible":true}],"show_social":false,"success_body":"We aim to respond within 24 hours. Keep an eye out on your mailbox!","success_button":"Send another message","success_heading":"Thanks for making the first step!","title_lines":["<p>Not sure where to start?</p>","<p><span class=\"mc-accent\">Lift the lid first.</span></p>"],"stamp":"Lid off"},"id":"gap-contact-employee-experience-widget","type":"contact"}]}],"id":"gap-contact-employee-experience-col"}],"customCss":null,"id":"gap-contact-employee-experience","layout":{"alignment":"left","columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false,"spaceTop":"full","spaceBottom":"full"},"schema_version":3,"scope":null,"strip_title":"Contact"}]$mc$::jsonb where slug = 'services/employee-experience';
update public.cms_pages set draft_page_rows = $mc$[{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"7725c7e1-51fa-4990-88a1-f81637fd3b3d","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"align":"left","answer":"A free pay transparency check for a small number of fast-growing companies of 10 to 150 people, in return for an honest review. Applications are read by hand and every applicant hears back within a week.","body":"<p>Each season we set aside time to help a small number of companies that are taking off or scaling fast, the moment when growth starts stretching everything that used to work. This season, that help is a free Pay Transparency Check.</p><p>We review your job adverts, interview scripts, contracts and pay criteria against the EU Pay Transparency Directive for every country you hire in, and hand you a ranked list of what to fix. In return, we ask for an honest review we can share on our website.</p>","color_label":"","label":"Free Pay Transparency Check","title_lines":["<p><span style=\"color: rgb(106, 1, 14)\">Growing fast?</span></p>","<p><span style=\"color: rgb(106, 1, 14)\">Let's check your pay before someone else does.</span></p>"],"visual_image_alt":"Stacks of coins being arranged by hand, representing pay structures","visual_image_url":"https://mbxqjjmjywsxibttjrgr.supabase.co/storage/v1/object/public/media-library/gemini-generated-image-1lo5ka1lo5ka1lo5-1789074775583-l5p6gz.webp","visual_layout":"half_bleed","title_size":"display"},"id":"655e717e-ea84-4c62-97d8-abe79575aa78","type":"hero"}]}],"id":"2daa09fd-b33f-46d7-8ffb-0317f0315cfa"}],"id":"a9384ffc-683b-4cc9-b736-204c947b7863","layout":{"alignment":"left","column_widths":[100],"columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false},"schema_version":3,"strip_title":"Hero"},{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"80853e60-9d71-4094-8d1e-129d7eef4948","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"body":"<p></p>","eyebrow":"WHO IT'S FOR","steps":[{"description":"<p>Companies of 10 to 150 people that have grown quickly in the last year, through hiring, funding or new markets.</p>","title":""},{"description":"<p>Teams hiring in at least one EU country, with salaries still set case by case.</p>","title":""},{"description":"<p>A founder or People lead who can share job adverts, contracts and pay data within a week.</p>","title":""},{"description":"<p>Someone happy to give an honest review of the work once it's done.</p>","title":""}],"subtitle":"Who we'd love to hear from.","subtitle_handwritten":true,"title_lines":[],"step_style":"cards"},"id":"d7b3a60c-d196-4125-9cb5-4eed202588f1","type":"process_steps"}]}],"id":"fc8f2e8a-84b0-4dbc-923d-b7889cfa0a22"}],"id":"338db143-8b22-4547-b47a-c128bef0d1cd","layout":{"alignment":"left","column_widths":[100],"columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false},"schema_version":3,"strip_title":"Who it's for"},{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"bb47e003-9b70-488b-880f-e7947d43b974","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"body":"<p></p>","eyebrow":"HOW IT WORKS","steps":[{"description":"<p>Tell us about your company in the form below. It takes five minutes.</p>","title":"Apply"},{"description":"<p>We read every application by hand and reply to each one, with a yes or a pointer to something useful.</p>","title":"Hear back within a week"},{"description":"<p>Over one to two weeks, we review your adverts, scripts, contracts and pay criteria, country by country, and make the quick fixes on the spot.</p>","title":"The check"},{"description":"<p>A one-hour call with your ranked gap list, a fixed price for closing each gap, and plenty of time for questions.</p>","title":"The walkthrough"},{"description":"<p>Once you've seen the results, a short, honest review we can publish.</p>","title":"Your review"}],"subtitle":"Five steps, about three weeks from application to walkthrough.","subtitle_handwritten":true,"title_lines":[],"step_style":"cards"},"id":"6b8bd607-e498-4935-8c54-3298776aa8af","type":"process_steps"}]}],"id":"1cf62173-78aa-4c6f-aa60-edd8582472e3"}],"id":"e905010d-7347-44d4-86ca-ff75e88b3dfc","layout":{"alignment":"left","column_widths":[100],"columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false},"schema_version":3,"strip_title":"How it works"},{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"c565a0ec-ae0c-4a7a-a6db-e5f472c637e7","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"body":"<p></p>","eyebrow":"WHAT YOU GET","steps":[{"description":"<p>Review of job adverts, interview scripts and application forms, with pay-history questions removed</p>","title":""},{"description":"<p>Contract and handbook check for pay-secrecy clauses</p>","title":""},{"description":"<p>A dated, country-by-country summary of the rules for everywhere you hire</p>","title":""},{"description":"<p>A template written reply for pay-information requests</p>","title":""},{"description":"<p>A ranked gap list, with a fixed price for closing each gap</p>","title":""},{"description":"<p>A one-hour walkthrough with the founders</p>","title":""}],"subtitle":"The same check as our paid Autopsy, in full.","subtitle_handwritten":true,"title_lines":[],"step_style":"cards"},"id":"bc41a802-e486-4bb8-8d78-4cd201cb84b0","type":"process_steps"}]}],"id":"b0722699-430d-4ee0-a5f5-a531071afbda"}],"id":"399c1b9f-2c80-47ee-bfdb-deead14cf2c3","layout":{"alignment":"left","column_widths":[100],"columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false},"schema_version":3,"strip_title":"What you get"},{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"61643487-85ce-4c99-adad-36bdec61e2b0","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"body":"<p></p>","eyebrow":"","items":[{"answer":"<p>Yes. The check is free for the companies we select. In return, we ask for an honest review we can share on our website, and permission to describe the work in general terms.</p><p>Any follow-on work, such as the job levels and pay bands in our <a href=\"/services/pay-transparency/\">Pay Transparency service</a>, is your choice, with a fixed price agreed upfront.</p>","question":"Is it really free?"},{"answer":"<p>A small number each season, so each check gets proper time. Places go to the companies where the check will make the biggest difference.</p>","question":"How many companies do you take?"},{"answer":"<p>Every applicant hears back within a week, with a pointer to a useful next step.</p>","question":"What if we aren't selected?"},{"answer":"<p>It sits alongside legal advice. We check your documents and processes against the rules and flag what needs a lawyer's sign-off; your employment lawyer confirms the local legal detail.</p>","question":"Is this legal advice?"},{"answer":"<p>A few honest sentences about what the check was like and what it changed, with your name and company if you're comfortable sharing them.</p>","question":"What does the review involve?"},{"answer":"<p>It's the same check, in full. The paid version, The Autopsy, starts from €750 and sits on our <a href=\"/services/pay-transparency/\">Pay Transparency</a> page.</p><p>The free check goes to a small number of fast-growing companies each season, in return for an honest review.</p>","question":"How is the free check different from The Autopsy?"}],"title_lines":["<p>Frequently asked questions</p>"]},"id":"11a673c3-7850-4515-bf5e-36a05f4326f2","type":"faq"}]}],"id":"49b12c5c-0501-4fe1-a118-8372773296a1"}],"id":"dc41d92a-e5bd-42c3-92dd-b1778fcb3952","layout":{"alignment":"left","column_widths":[100],"columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false},"schema_version":3,"strip_title":"FAQ"},{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"65c70f56-9a17-427a-b621-ad61b07b152e","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"body":"<div>Tell us about your company and we'll reply within a week.</div>","button_text":"Apply for a free check","fields":[{"key":"name","label":"Your name","required":true,"type":"text","visible":true},{"key":"email","label":"Work email","required":true,"type":"email","visible":true},{"key":"company","label":"Company and website","required":true,"type":"text","visible":true},{"key":"message","label":"About your company: headcount, countries you hire in, how fast you've grown, and what's prompting the pay question","required":true,"type":"textarea","visible":true},{"key":"marketing","label":"Keep me updated with insights and articles","required":false,"type":"checkbox","visible":true}],"show_social":false,"success_body":"We read every application by hand and reply within a week.","success_button":"Send another message","success_heading":"Application received.","title_lines":["<p>Apply for a free</p>","<p>Pay Transparency Check.</p>"]},"id":"c3275c8a-5ec6-4a9d-9517-8c49c6b1676d","type":"contact"}]}],"id":"dbdfe4a1-5235-4480-a2cc-2b40ca255eaa"}],"id":"c4402dc3-8064-4110-8c4c-57d8eb6b1914","layout":{"alignment":"left","column_widths":[100],"columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false},"schema_version":3,"strip_title":"Apply"}]$mc$::jsonb where slug = 'pay-transparency-check';
update public.cms_pages set draft_page_rows = $mc$[{"bg_color":"","column_layout":"custom","columns":[{"cell_direction":"vertical","cells":[{"id":"8d203e0a-0569-4cbc-9212-77df535343aa","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"answer":"I am Robert Stănescu, a people and communications leader who has worked across 36 countries and now runs The Magic Coffin as a one-person consultancy from Sweden, remote-first, for companies anywhere that need senior help ahead of a full department. I cover internal communications, employee experience, people operations, fractional HRBP, pay transparency and manager enablement.","bg_type":"none","bg_url":"","body":"<p>I am Robert Stănescu, a people and communications leader who has worked across 36 countries and now runs The Magic Coffin as a one-person consultancy from Sweden, remote-first, for companies anywhere that need senior help ahead of a full department. I cover internal communications, employee experience, people operations, fractional HRBP, pay transparency and manager enablement.</p>","body_color":"","color_label":"","color_tagline":"","label":"The Magic Coffin · Est. 2026","label_color":"","subtitle":"","subtitle_color":"","tagline":"Internal Communications · Employee Experience · People Operations · Fractional HRBP · Pay Transparency · Manager Enablement","title_color":"","title_lines":["<p>This is your</p>","<p><span class=\"mc-accent mc-accent-gold\">Vampire Slayer.</span></p>"],"align":"left","title_size":"display","visual_image_url":"https://mbxqjjmjywsxibttjrgr.supabase.co/storage/v1/object/public/editor-images/gallery/1788857158659-7hkgtb3j2hi.jpg","visual_layout":"half_bleed","visual_image_focal_x":42,"visual_image_focal_y":74,"tagline_style":"chips","cta_label":"Book a free consultation","cta_url":"#contact"},"id":"1351bb01-d1ee-4b4d-9813-a5affdcd9cc7","type":"hero"}]}],"id":"797273c1-3b82-44f2-83fa-88fbfb8c7966"}],"customCss":null,"id":"f1ee64eb-9786-4b18-b507-6732ea920ae1","layout":{"columns":1,"fullWidth":false,"heightMode":"auto","marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"alignment":"left","snapEnabled":false,"spaceTop":"lead","spaceBottom":"none"},"schema_version":3,"scope":null,"strip_title":"Hero"},{"bg_color":"","column_layout":"50-50","columns":[{"cell_direction":"vertical","cells":[{"id":"2b37362d-c416-43ac-8ca8-3832f42852dd","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"body":"","color_eyebrow":"","eyebrow":"The Summoning","subtitle":"","title_lines":["<p>Every haunted organisation has a <span class=\"mc-accent\">vampire moment.</span></p>"]},"id":"5e340b28-b3fa-4c5a-bc12-bdd3d6d624c0","type":"text"}]}],"id":"d2d8e8b5-6a88-4b9c-9bae-e174fbcf8370"},{"cell_direction":"vertical","cells":[{"id":"342adffd-7176-4680-ae51-7f17722b1fd2","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"body":"<p><strong>2010</strong>.&nbsp;&nbsp;I'm in middle school, and I've just discovered True Blood, a show about vampires having a great deal of sex in the American South, which is not obviously what a middle schooler should be watching, and yet. For about eight months I am insufferable about vampires in a way only a kid that age, with that little else going on, can be.<br></p><p>I do what any self-respecting kid with a Facebook account does with a new obsession: I turn my parents' living room into a place. Not a place-place, a Facebook check-in. I call it Robby's Magic Coffin for Stupid Vampires, and I use it to tag my own status updates, for no reason anyone could defend, least of all me.<br></p><p>Years pass, and what happens next looks less like a career and more like a string of shifts. I wait tables and pull pints on weekends at Leicester Tigers and the Ricoh Arena, freeze through an English winter asking strangers on the street to fund a guide dog, then spend a year telling people over the phone that their fridge has died and a replacement is on its way. I become a bank teller in Coventry. Then Klarna: first talking distressed customers back from the edge of a decision they'll regret, then training the people who talk to distressed customers, and it's in that second job, watching someone's face change mid-session when a piece of training lands, that I work out what I've secretly wanted to do the whole time: become a part of people's adventures at work.</p><p>Also, somewhere in all of this, I collect two degrees, one in Social Anthropology and one in Media and Communication, mostly because no one could tell me no.<br></p><p>Then South Pole: three and a half years being the face of internal communications, DEI and HR Project Management for a 1,300-person sustainability consultancy spread across 36 countries, for a company that was truly helping bring true climate impact for all. I watched it shrink by a third, in three separate rounds, being a part of the process that carried each one. The fourth round was the one where I stopped writing the letter, or even being in the room, and when I finally got to reading it.</p><p>Somewhere in the middle of figuring out what came next, the coffin came back. Not the vampires, the coffin. Turns out the name I gave a Facebook check-in as a bored kid was, unintentionally, the best description I've ever come up with for what I actually do, and looking back at the shift-to-shift years, I can see why nobody warned me: a person who has replaced fridges, talked someone off a financial ledge, and trained a room full of strangers to do their jobs slightly better has, without meaning to, learned to spot the exact same problem wearing a different uniform in every building he's ever worked in. HR calls it engagement. Comms calls it silence. Ops calls it a spreadsheet nobody updates. I call it a vampire moment: the place in an organisation where something is quietly being drained, and nobody with the right job title is looking at it. I couldn't call the business what I called the check-in, obviously. You cannot build client relationships on the word \"stupid\". So Stupid Vampires became Silly Vampires, which is really just Stupid Vampires but wearing Ralph Lauren.</p><p>None of this is dramatic, which is exactly the problem. It's the all-hands email nobody reads. The onboarding programme that quietly stops existing after week one. The engagement survey that produces a number, goes into a slide, and is never mentioned again. I spent a winter freezing on doorsteps for a charity because a stranger's five minutes of attention was worth fighting for. That's the actual job now, not raising the dead: organisations, leaders and new entrepreneurs building something for the first time summon me in for the same reason, a fresh eye on the exact meeting, the exact email, the exact line item where something started dying, while there's still enough of it left to save, so the business and the people running it can thrive together. Happy wife, happy life, they say. They surely haven't seen how productive a company gets when the employee is the happy one.</p>","subtitle":"","title_lines":[]},"id":"f917abe0-a4af-4d79-88b2-52f269aced6f","type":"text"}]}],"id":"1d15c055-82ca-44d4-98b3-9e85ef146749"}],"id":"3e2d121c-0048-4ee8-a74c-9fc879fb34c4","layout":{"alignment":"left","blockAlign":"stretch","columnGap":"tight","column_widths":[33,67],"columns":1,"fullWidth":false,"heightMode":"auto","marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false,"spaceTop":"full","spaceBottom":"full"},"schema_version":3,"strip_title":"The Summoning"},{"bg_color":"","column_layout":"custom","columns":[{"cell_direction":"vertical","cells":[{"id":"ec98c914-f6c0-4cf2-afd8-fde85da8513a","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"body":"<p></p>","color_eyebrow":"","eyebrow":"Why the Coffin?","steps":[{"description":"<p>Run it, get a number, drop it in a slide, forget it by Friday. That's a seance for a culture that left the building, dressed in engagement's clothes, and the ninety days of silence after prove it. Everyone bloody clocks it.</p>","title":"Your engagement survey is a hack."},{"description":"<p>It's the fine print of the job description: implied everywhere, spelled out almost nowhere, and it outworks anything printed in bold. Once you see it, you can help the employees HR is trying to protect.</p>","title":"HR protects the company first."},{"description":"<p>Culture shows up the one time someone asks an uncomfortable question in a town hall: the room stops watching the slide and starts watching leadership's face, waiting for the flinch, or they reach for garlic.</p>","title":"Culture is safety during conflict."}],"title_lines":["<p>Some things get buried. <span class=\"mc-accent\">These stay exposed.</span></p>"],"step_style":"cards"},"id":"24bdd328-563f-4d95-8708-3def3fe44d76","type":"process_steps"}]}],"id":"68789a2a-789f-4628-a8f3-049536ace9d3"}],"customCss":null,"id":"328628b5-4578-4fc3-a66d-a821e449be36","layout":{"alignment":"left","columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":72,"paddingTop":72,"snapEnabled":false,"spaceTop":"none","spaceBottom":"full"},"schema_version":3,"scope":null,"strip_title":"Why the Coffin?"},{"bg_color":"","column_layout":"custom","columns":[{"cell_direction":"vertical","cells":[{"id":"3d38caba-3b0b-4ff7-bfe1-fc5cde57f238","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"body":"<p>I'm the internal comms specialist, the people ops person, the HR business partner, the pay-band builder and the new-manager coach a scale-up needs, running as one person instead of five job postings. I write every word, build every workflow and sit in every uncomfortable meeting myself, direct line, always, whether that's wiring HiBob and support tickets together so it all holds, or telling a founder their onboarding is bleeding new hires by week three. Ask me the question you've been avoiding asking your own team, chances are I've sat on both sides of it already.</p><p>Away from client work, quick facts:</p><ul><li><p>Loud extrovert at a dinner party who somehow also needs four hours alone afterwards to recover, and I've made peace with the contradiction.</p></li><li><p>Three degrees deep already (Sociology, Social Anthropology, Media and Communication), starting a fourth in Management, because apparently one field was always going to be too small.</p></li><li><p>Salut, hello, hola, bună, hej, and most important of all: yass, huntee! I speak six languages (if you count sass one of them) well enough to get by, but the one language I speak best is people.</p></li><li><p>Grew up on Pokémon, spent a chunk of my twenties deep in random MMORPGs and these days it's Teamfight Tactics and the Sims 4 keeping me up too late.</p></li><li><p>Give me a project I care about and I'll outlast anyone on it. Give me a promotion for its own sake and I'll shrug. I'd rather be trusted to get on with the work than watched while I do it.</p></li><li><p>Volunteer with CinemaQueer, Stockholm's queer film crowd, and I'm slowly writing a gothic, post-climate-crisis novella that has everything to do with why the vampire thing makes sense to me.</p></li></ul><p>If any of this sounds like your organisation, let's talk.</p>","color_body":"","color_credential_bg":"","color_credential_text":"","color_eyebrow":"","color_name":"","color_role":"","color_title":"","credentials":["MSc Social Anthropology 🏺","MSc Media & Comms 🎙️","PSM I Certified 🧢","BA (Hons) Sociology 👥","Grew up in Romania 🇷🇴","Started my career in England 🏴󠁧󠁢󠁥󠁮󠁧󠁿","Developed it in Sweden 🇸🇪","Expanding it across the world 🗺️"],"eyebrow":"The Medium","image_alt":"Robert Stănescu, founder of The Magic Coffin","image_url":"https://mbxqjjmjywsxibttjrgr.supabase.co/storage/v1/object/public/editor-images/gallery/1775210694292-nrxkj389dvh.png","name":"Robert Stănescu","role":"Founder & Principal Consultant","title_lines":["<p>This is who I am</p><p></p><p></p>"],"layout_style":"portrait"},"id":"920c0ca6-df6f-4a1b-b5c1-ba42c1f6ccc0","type":"profile"}]}],"id":"097fa30c-030f-4753-a1cf-8e69b5e16a3a"}],"customCss":null,"id":"8ce56223-21d5-489b-8e41-15bd8f2ed846","layout":{"alignment":"left","columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false,"spaceTop":"tight","spaceBottom":"full"},"schema_version":3,"scope":null,"strip_title":"This is who I am"},{"bg_color":"","column_layout":"custom","columns":[{"cell_direction":"vertical","cells":[{"id":"863099ba-bbfc-4a2f-9ef5-93b4cfc28f69","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"body":"","color_eyebrow":"","color_note":"","color_stat":"","color_stat_label":"","color_tile_bg":"","eyebrow":"Proof you can check","items":[{"label":"internal page views generated in a single year","value":"300K+"},{"label":"countries run simultaneously, one comms function","value":"36"},{"label":"employees supported through 3 redundancy rounds with legal-compliant, cascaded comms","value":"~500"},{"label":"countries with live Magic Coffin clients: UK, US, Australia, Sweden, Germany, Spain","value":"6"}],"title_lines":["<p>Numbers instead of adjectives.</p>"],"band_style":"deep"},"id":"119da0a3-2f24-43c4-89a2-9dbe8a031f34","type":"proof_band"}]}],"id":"2aa5b547-125e-4021-a2d4-79f55e6a3a3b"}],"customCss":null,"id":"f6de6b20-05c2-424f-a3cd-b9b0a13e7c94","layout":{"alignment":"left","columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":56,"paddingTop":56,"snapEnabled":false,"spaceTop":"none","spaceBottom":"none"},"schema_version":3,"scope":null,"strip_title":"Proof you can check"},{"bg_color":"","column_layout":"custom","columns":[{"cell_direction":"vertical","cells":[{"id":"57d49274-9cef-4a95-be84-87647acc834d","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"cards":[{"body":"<div>Usually between fifty and around two thousand people, where the employee experience or HR operations are collapsing under growth pressure while everyone's too busy shipping to notice.</div>","icon":"lucide:TrendingUp","title":"Scale-ups growing faster than their infrastructure","variant":"glass"},{"body":"HR leaders who already know comms, EX, People Ops, pay or manager training needs work, running short on in-house capacity and specialist hands, with a full-time HRBP still a budget line away.","icon":"lucide:Puzzle","title":"People teams stretched across every hat","variant":"glass"},{"body":"Running the same onboarding, the same policy, the same town hall across four time zones, and getting a different result in each one.","icon":"lucide:Globe","title":"Globally distributed organisations","variant":"glass"},{"body":"Restructures, cultural pivots, rapid expansion, HR system rollouts, new EU pay transparency rules, moments where precise, humane execution is the difference between trust and damage.","icon":"lucide:Zap","title":"Leaders navigating hard moments","variant":"glass"}],"color_card_body":"","color_card_title":"","color_eyebrow":"","color_note":"","color_title":"","eyebrow":"Who I Work With","note":"","title_lines":["<p>The right fit matters more than the right brief.</p>"],"marker_style":""},"id":"ccd96096-df68-443f-bff4-ff47ad3eb4c7","type":"boxed"},{"data":{"body":"","subtitle":"","title_lines":[]},"id":"7a8a3473-0adf-4b50-b058-cfb5b66df9ab","type":"text"}]}],"id":"20a7d43d-d1c0-4aad-9ee8-c1d1cfd83151"}],"customCss":null,"id":"033ea282-3ecb-4677-9d94-9771392d894b","layout":{"alignment":"left","columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false,"spaceTop":"full","spaceBottom":"none"},"schema_version":3,"scope":null,"strip_title":"Who I work with"},{"bg_color":"","column_layout":"custom","columns":[{"cell_direction":"vertical","cells":[{"id":"3974a434-800e-492e-b9b7-8bc8e5835b18","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"body":"<div>Book a free 30-minute call. I'll tell you, honestly, whether I'm the right person to fix it, or whether you're better off elsewhere.</div>","button_text":"Book a free consultation","fields":[{"key":"name","label":"Your name","required":true,"type":"text","visible":true},{"key":"email","label":"Email address","required":true,"type":"email","visible":true},{"key":"company","label":"Company","required":false,"type":"text","visible":true},{"key":"message","label":"Tell us about your vampire moment","required":true,"type":"textarea","visible":true},{"key":"marketing","label":"Keep me updated with insights and articles","required":false,"type":"checkbox","visible":true}],"show_social":false,"success_body":"I respond within 24 hours.","success_button":"Send another message","success_heading":"Message received.","title_lines":["<p>Wondering where to start?</p>","<p><span class=\"mc-accent\">Lift the lid first.</span></p>"],"stamp":"Lid off"},"id":"85c8e570-cdb5-4400-9d12-ee8b11bfc3fb","type":"contact"}]}],"id":"95bb4d9d-1222-417d-b954-b624304060b5"}],"customCss":null,"id":"11d1f56d-72e3-4dce-916b-5141c5538986","layout":{"alignment":"left","columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"verticalAlign":"middle","snapEnabled":false,"spaceTop":"full","spaceBottom":"full"},"schema_version":3,"scope":null,"strip_title":"Contact"}]$mc$::jsonb where slug = 'about-us';
update public.cms_pages set draft_page_rows = $mc$[{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"26c29945-a700-4fe6-abcd-dcc6e6517b85","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"align":"left","answer":"People operations consulting for companies of 50 to 2,000 people that have outgrown their HR admin. I audit the systems, fix the processes and run them with you, remote-first from Sweden, for teams anywhere.","body":"<p>The parts of a company you only notice once they break. The process that routes a question to the right person instead of a group chat. The paperwork that turns a promotion into an actual pay rise, on time, in an afternoon rather than three weeks of email back and forth. The onboarding flow that survives a manager forgetting to show up.</p><p>We build the operational skeleton so the organisation runs on written processes instead of someone's memory and a shared spreadsheet. This is the service The Magic Coffin already runs for current clients, month in and month out.</p>","color_label":"#6A010E","label":"People Operations","title_lines":["<p><span style=\"color: rgb(106, 1, 14)\">Zombie processes go on autopilot.</span></p>","<p><span style=\"color: rgb(106, 1, 14)\">They need some new brainpower.</span></p>"],"visual_image_alt":"Let's fix what puzzled you in People Ops","visual_image_url":"https://mbxqjjmjywsxibttjrgr.supabase.co/storage/v1/object/public/editor-images/gallery/1788860647930-s9e1a47sym.jpg","visual_layout":"half_bleed","title_size":"compact","label_dot":true,"cta_label":"Book a free consultation","cta_url":"/#contact","answer_strip":true,"visual_badge_label":"Start with","visual_badge_title":"The Autopsy","visual_badge_text":"People Operations Audit · From €900"},"id":"caf1b7d9-7bdb-4651-a1d5-b3727ba0a817","type":"hero"}]}],"id":"3bd451ec-2e43-4f51-bb0f-b98be5b15339"}],"id":"1cf62c3e-a5f1-4def-a113-bb516d35dad7","layout":{"alignment":"left","column_widths":[100],"columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false,"spaceTop":"lead","spaceBottom":"none"},"schema_version":3,"strip_title":"Hero"},{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"33715c71-a36e-4780-9240-00633f4783e7","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"body":"<p></p>","eyebrow":"WHO IS THIS FOR","steps":[{"description":"<p>Ambitious about what the company is building, and honest about what that ambition can fairly ask of the people paid to help build it. Passion is welcome, as long as it stays the founder's job to carry. Roughly 50 up to 2,000 people: past the point where one person can carry every process in their head.</p>","title":""},{"description":"<p>Multi-country or multi-entity operations, where contract, compliance and query handling complexity multiplies faster than the team supporting it.</p>","title":""},{"description":"<p>A People function that's currently one generalist doing HRBP work, comms and operations all at once, where operations is the piece quietly falling behind.</p>","title":""},{"description":"<p>On the first call, this is the thing I'm listening for: was the employee part of the decision, or just the paperwork after it.</p>","title":""}],"subtitle":"Built for the scale-up where informal process has stopped holding.","subtitle_handwritten":true,"title_lines":[],"step_style":"cards","subtitle_as_title":true,"last_step_as_note":true},"id":"5d78ba1d-66cd-47f8-b770-64ad3c818915","type":"process_steps"}]}],"id":"68edcd05-8b0e-42e0-a7da-2024fd4a5269"}],"id":"05030dcd-ab20-4a8d-ae8d-12868a49c571","layout":{"alignment":"left","column_widths":[100],"columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false,"spaceTop":"full","spaceBottom":"near"},"schema_version":3,"strip_title":"How We Work"},{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"d7a41cbb-52a6-46b9-a220-166aeea6d83b","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"__design":{"bgColor":"","borderRadius":0,"customCss":"","marginBottom":0,"marginLeft":0,"marginRight":0,"marginTop":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"visibility":{"desktop":true,"mobile":true}},"caption_position":"bottom-left","color_caption_bg":"","color_caption_text":"","color_description":"","color_eyebrow":"","color_title":"","description":"<p>People operations is the discipline behind contracts, compliance and queries: the parts of the business you only notice in the one week they stop running properly.</p><p>We build the version that keeps running while you are in another room.</p>","eyebrow":"What good looks like","floating_caption":"","image_alt":"Organised filing shelves representing structured, reliable people operations systems","image_position":"left","image_shape":"default","image_url":"https://mbxqjjmjywsxibttjrgr.supabase.co/storage/v1/object/public/media-library/people-operations-1788701891862-4x5hwl.jpg","split_widths":[33,67],"title":"The systems that hold when nobody is watching.","title_lines":["<p>The systems that hold when nobody is <span class=\"mc-accent\">watching.</span></p>"],"panel_style":"pillar","pillar":"people-operations"},"id":"2d3ad9bb-c3d3-4312-a1d7-cae3def53e33","type":"image_text"}]}],"id":"830d3c30-4fcf-4473-b5cf-6427e9d8db11"}],"id":"3c2a4b22-2dd4-4daf-bfea-98a3d7f5f968","layout":{"alignment":"left","columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":56,"paddingTop":56,"snapEnabled":false},"schema_version":3,"scope":null,"strip_title":"What Good Looks Like"},{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"e40a02de-27f3-4e68-8117-4abd7e580478","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"cards":[{"body":"A process runs because one person remembers every step of it. The moment that person is on holiday, or leaves, the whole system stalls, and everyone downstream finds out exactly how much of the operation was running on memory alone. By then two people own a version of it, they each answer differently, and the fix costs more than the original gap did.","icon":"lucide:CircleAlert","title":"The problem","variant":"dark"},{"body":"Systems built at real scale: HRIS automation, a self-service query system and compliance training, for an 800 to 1,300 person, 36 country organisation. Real brainpower, applied to processes that had been running on memory alone.","icon":"lucide:Settings2","title":"A background built for exactly this","variant":"glass"},{"body":"A social sciences background (anthropology, sociology, media and communication) means the fix accounts for how people really use a system, beyond how it is meant to work on paper. The best-designed workflow still fails the day people quietly route around it.","icon":"lucide:GraduationCap","title":"Someone who understands the people behind the process","variant":"glass"}],"eyebrow":"Why The Magic Coffin","title_lines":["<p>Here's the problem, and here's the fix.</p>"],"marker_style":"bar"},"id":"10ef880a-69dc-480e-8353-8566fa784848","type":"boxed"}]}],"id":"0f37e1df-7627-445c-bc80-c7fab1428863"}],"id":"83571d3d-d239-4b17-ad3e-05199332b82c","layout":{"alignment":"left","columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":56,"paddingTop":56,"snapEnabled":false,"spaceTop":"full","spaceBottom":"tight"},"schema_version":3,"scope":null,"strip_title":"Why The Magic Coffin"},{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"rs-e4c27cf9-f810-4553-8f1d-6cd2898ae72d-service-cell0","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"card_text_align":"left","color_card_bg":"","color_card_description":"","color_card_title":"","color_carousel_btn_bg":"","color_carousel_btn_fg":"","color_cta_text":"","color_cta_time":"","color_deliverables_bg":"","color_deliverables_label":"","color_divider_from":"","color_divider_to":"","color_dot_active":"","color_dot_inactive":"","color_heading":"","color_heading_sub":"","color_label":"","color_meta_bg":"","color_meta_fg":"","color_note_border":"","color_primary":"","color_section_bg":"","color_subtitle":"","description":"<p>Every engagement starts with a free 30-minute call, where you get a straight answer including an honest read on fit.</p>","eyebrow":"Engagements","pillar_number":"Pillar 03","services":[{"deliverables":["Stakeholder interviews across People, Ops and at least one line manager","Full inventory of current HR systems (HRIS, ATS, LMS, ticketing or query tools) and how they're actually used versus how they're supposed to be used","Full lifecycle review: onboarding, offboarding, contract/comp changes, compliance training, employee query handling","Identification of single points of failure: processes with no documentation and no backup person","Written findings report (15–25 pages), same direct, no-corporate-fog standard as the other Autopsies","Prioritised 30/60/90-day action roadmap"],"description":"Before you fix anything, you need to know what's actually broken versus what just feels broken. The Autopsy maps every people-ops process you run today: onboarding, offboarding, contract changes, compliance training, employee queries, the lot. We find where a human is manually doing what a system should be doing, where a process only exists in one person's head, and where you're one sick day away from something quietly failing. Done looks like: every people-ops process you run today written down in one place, each with a named owner and a named backup, and every process still running on one person's memory listed by name.","note":"The Autopsy is the natural starting point for most clients, and it almost always reveals enough to warrant either a Reanimation or a Covenant. Consider it an investment that pays for itself.","price":"Book a free consultation","subtitle":"People Operations Audit","tag":"Fixed project","tagType":"fixed","time":"From €900 · 2–3 weeks · ~15–20 hours","title":"The Autopsy","startHere":"start here"},{"deliverables":["Tiered self-service query system design (a genuine deflection layer, not a FAQ page nobody opens)","HRIS workflow build and automation (contract changes, comp/salary review cycles, role changes)","Compliance and mandatory training programme setup in your LMS, if you don't already have one running","System configuration documentation, so the setup survives you changing HR tools later","Integration and workflow testing before go-live","Full handover session + 90-minute admin training"],"description":"This is where the machinery actually gets built. We design and implement the systems that should have existed already: a tiered self-service query system that answers routine questions before they reach a human, HRIS workflows that make a contract or comp change take an afternoon instead of three weeks of email, and compliance training that runs itself instead of chasing people every quarter. You get working systems, configured and handed over. Done looks like: a tiered query system live, with a measured share of routine questions answered before they reach a human, and that share reported back to you at handover.","price":"Book a free consultation","subtitle":"HR Systems & Tooling Implementation","tag":"Fixed project","tagType":"fixed","time":"From €2,000 · 4–6 weeks · ~35–45 hours","title":"The Reanimation"},{"deliverables":["Onboarding and offboarding journey design: touchpoints, owners, timing","Policy documentation and handbook design or update","Process playbook: written, practical, branded, actually usable on a Monday morning","SLA definitions for people-ops requests: turnaround expectations, escalation paths","Manager-facing process guide","Handover session + team training"],"description":"Systems only work if the people using them know what they're supposed to do. The Covenant is the human-facing half of People Ops: the onboarding and offboarding journeys, the policy documentation, the process playbook that tells your team what to do and when, with the answer written down before anyone has to ask you. Done looks like: your onboarding and offboarding running to a written sequence with named owners and stated turnaround times, followed by a manager working from the guide alone.","price":"Book a free consultation","subtitle":"Onboarding, Offboarding & Policy Design","tag":"Fixed project","tagType":"fixed","time":"From €1,400 · 4–5 weeks · ~25–30 hours","title":"The Covenant"},{"deliverables":["Monthly ops review with your People or Ops lead","Contract and comp/addendum change processing (via HiBob or your HRIS)","Onboarding and offboarding administration","Policy and process documentation maintenance","Employee query support and triage","Monthly ops report: what moved, what's outstanding, what needs a decision from you"],"description":"People Ops is upkeep. The Resurrection keeps the systems running monthly: processing contract and comp changes, maintaining and updating policies, handling onboarding and offboarding admin, keeping the HRIS configuration current as you grow. In practice, this is the same service The Magic Coffin already runs for its current clients, formalised into a named tier. Done looks like, every month: contract and comp changes processed inside the turnaround we agree, policies current, and a report showing what moved, what is outstanding, and what needs a decision from you.","note":"The 3-month minimum is a commitment to your results: operational infrastructure takes longer than four weeks to settle.","price":"Book a free consultation","subtitle":"Fractional People Ops Partner","tag":"Monthly Retainer","tagType":"retainer","time":"From €900 a month · Minimum 3-month commitment · ~14–20 hrs/mo","title":"The Resurrection"}],"title":"What we can help with","card_layout":"grid","pillar":"people-operations"},"id":"a9b11d89-6ff4-460a-8601-ec5695967716","type":"service"}]}],"id":"rs-e4c27cf9-f810-4553-8f1d-6cd2898ae72d-service-col"}],"id":"e4c27cf9-f810-4553-8f1d-6cd2898ae72d","layout":{"alignment":"left","column_widths":[100],"columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false,"spaceTop":"full","spaceBottom":"tight"},"schema_version":3,"strip_title":"Engagements"},{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"rs-e4c27cf9-f810-4553-8f1d-6cd2898ae72d-faq-cell0","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"body":"<p></p>","eyebrow":"FAQ","items":[{"answer":"<p>Vendor-agnostic by default.</p><p>The Autopsy assesses what you have and what's actually needed. The Reanimation recommends new tooling only where the gap survives better configuration or better use of what's already in place.</p>","question":"Do you recommend specific HRIS/ATS vendors, or is this vendor-agnostic?"},{"answer":"<p>That's precisely what the Autopsy is built to surface.</p><p>Interviews with the people who actually run the process day to day, cross-checked against what the systems show, to reconstruct what's really happening versus what's supposed to be happening.</p>","question":"What if our processes are undocumented, how do you audit something that only exists in someone's head?"},{"answer":"<p>Out of scope for the core Autopsy and Reanimation deliverables.</p><p>Payroll accuracy and processing sit with your payroll provider or accountant.</p><p>Where a people-ops process feeds payroll (comp changes, contract updates), that handoff is covered. Running payroll itself stays with your provider.</p>","question":"Does this cover payroll, or is that out of scope?"},{"answer":"<p>Yes, and it often should.</p><p>An external compliance review is exactly the kind of pressure that exposes undocumented single points of failure.</p><p>Flag it on the discovery call, so the engagement can be sequenced around it.</p>","question":"Can this run in parallel with an active compliance review?"},{"answer":"<p>The system that should handle a contract change, a comp update, a role change or a compliance training reminder in a couple of clicks, rather than three weeks of email back and forth.</p><p>Where yours falls short of that, closing the gap is the Reanimation's job.</p>","question":"What's an HRIS, in plain terms?"},{"answer":"<p>People Operations builds and runs the systems and paperwork: onboarding flows, HRIS workflows, policy documentation. It's the operational half of HR.</p><p><a href=\"/services/fractional-hrbp\">Fractional HRBP</a>, a separate pillar, brings judgement to the sensitive, infrequent calls: a restructure, a difficult exit, a comp decision that sets precedent.</p><p>Job levels, pay bands and the EU pay transparency rules sit with <a href=\"/services/pay-transparency\">Pay Transparency</a>, a focused slice of the same work.</p><p>Many clients need more than one, at different moments.</p>","question":"Is People Operations the same as HR?"}],"title_lines":["<p>Frequently asked questions</p>"],"subtitle":"If yours isn't here, that's what the free consultation is for."},"id":"9c2e32da-c389-4369-bfd2-5e779ff8f5ce","type":"faq"}]}],"id":"rs-e4c27cf9-f810-4553-8f1d-6cd2898ae72d-faq-col"}],"id":"rs-e4c27cf9-f810-4553-8f1d-6cd2898ae72d-faq","layout":{"alignment":"left","column_widths":[100],"columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false,"spaceTop":"full","spaceBottom":"tight"},"schema_version":3,"strip_title":"FAQ"},{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"3c15fec0-36ea-4690-8903-74ac7f50781a","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"categories":["People Operations & AI"],"color_eyebrow":"","color_title":"","eyebrow":"Latest thinking","limit":3,"link_label":"All blogs & insights","title":"From the blog"},"id":"b5118c45-a9a5-4e75-92eb-f33f733d3e74","type":"from_the_blog"}]}],"id":"52605d3f-4a62-4a02-899a-e596a6245a94"}],"id":"83ca3a25-a7ce-493e-a941-09fdbac4a4e8","layout":{"alignment":"left","column_widths":[100],"columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false,"spaceTop":"full","spaceBottom":"none"},"schema_version":3,"strip_title":"From the blog"},{"bg_color":"","column_layout":"custom","columns":[{"cell_direction":"vertical","cells":[{"id":"gap-contact-people-operations-cell","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"body":"Book a free 30-minute consultation. We'll identify your biggest vampire moment and tell you honestly whether we're the right fit to bury it.","button_text":"Book a free consultation","fields":[{"key":"name","label":"Your name","required":true,"type":"text","visible":true},{"key":"email","label":"Email address","required":true,"type":"email","visible":true},{"key":"company","label":"Company","required":false,"type":"text","visible":true},{"key":"message","label":"Tell us about your vampire moment","required":true,"type":"textarea","visible":true},{"key":"marketing","label":"Keep me updated with insights and articles","required":false,"type":"checkbox","visible":true}],"show_social":false,"success_body":"We aim to respond within 24 hours. Keep an eye out on your mailbox!","success_button":"Send another message","success_heading":"Thanks for making the first step!","title_lines":["<p>Not sure where to start?</p>","<p><span class=\"mc-accent\">Lift the lid first.</span></p>"],"stamp":"Lid off"},"id":"gap-contact-people-operations-widget","type":"contact"}]}],"id":"gap-contact-people-operations-col"}],"customCss":null,"id":"gap-contact-people-operations","layout":{"alignment":"left","columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false,"spaceTop":"full","spaceBottom":"full"},"schema_version":3,"scope":null,"strip_title":"Contact"}]$mc$::jsonb where slug = 'services/people-operations';
update public.cms_pages set draft_page_rows = $mc$[{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"d3d8f522-5864-4e4c-b53b-d7ff46f2603c","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"align":"left","answer":"A fractional HR business partner for founders who need senior people judgement at a lighter commitment than a full-time hire: restructures, difficult exits, pay decisions and the conversations everyone puts off. From a single hard-moment engagement to a monthly retainer, remote-first from Sweden, working globally.","body":"<p>Plenty of companies reach a size where the People decisions get too sensitive to delegate to managers and too infrequent to justify a full-time hire: the restructure, the difficult exit, the comp call that will set precedent, the manager who needs to be told something uncomfortable before it becomes a resignation letter.</p><p>Fractional HRBP puts a senior partner in the room for exactly those moments, for one engagement or month by month.</p>","color_label":"#003728","label":"Fractional HRBP","subtitle":"","tagline":"","title_lines":["<p><span style=\"color: rgb(0, 55, 40)\">By the time HR calls me,</span></p>","<p><span style=\"color: rgb(0, 55, 40)\">the body's already cold.</span></p>"],"visual_image_alt":"Confidentiality and empathy serve best for a HRBP","visual_image_url":"https://mbxqjjmjywsxibttjrgr.supabase.co/storage/v1/object/public/editor-images/gallery/1788860820254-eazc35wt2xm.jpg","visual_layout":"half_bleed","title_size":"compact","label_dot":true,"cta_label":"Book a free consultation","cta_url":"/#contact","answer_strip":true,"visual_badge_label":"Start with","visual_badge_title":"The Vigil","visual_badge_text":"Single Hard-Moment Support · From €500 a day"},"id":"00a89a18-f865-498b-bf32-c4fdd95b8cf6","type":"hero"}]}],"id":"405d7ed3-7234-41c0-a73a-3d1b331a4ddb"}],"id":"3c698427-0dde-439d-a1b7-62872734f248","layout":{"alignment":"left","column_widths":[100],"columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"verticalAlign":"middle","snapEnabled":false,"spaceTop":"lead","spaceBottom":"none"},"schema_version":3,"strip_title":"Hero"},{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"9b1d5e4c-aba9-487e-8bbf-d14644c323f4","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"cards":[{"body":"A senior HR Business Partner who works with you part time or per engagement, bringing the judgement of a senior hire at a lighter commitment.","icon":"lucide:UserCheck","title":"A fractional HRBP, in plain terms","variant":"glass"},{"body":"A leadership team that picks up the phone before the decision lands, while there's still time to shape it well. A restructure where the people affected hear it from a real person, in a real conversation. A senior HR voice in the room for the call that matters most, there exactly when it's needed.","icon":"lucide:PhoneCall","title":"A senior voice, exactly when the moment calls for it","variant":"glass"}],"color_card_body":"","color_card_title":"","eyebrow":"","title_lines":["<p></p>"],"marker_style":"bar"},"id":"c739c435-cb50-47ec-9c8d-71e23a9591e8","type":"boxed"}]}],"id":"06e3e816-0e55-41b5-afed-e8405c7d8fc5"}],"id":"421ea531-15d0-4bcf-932c-31852c29fa9a","layout":{"alignment":"left","columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":56,"paddingTop":56,"snapEnabled":false,"spaceTop":"full","spaceBottom":"tight"},"schema_version":3,"scope":null,"strip_title":"What This Is & What Good Looks Like"},{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"65e6e436-0e7f-4209-9ceb-862b42372441","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"body":"<p></p>","eyebrow":"WHO THIS IS FOR","steps":[{"description":"<p>A founder, Head of People or COO facing a restructure, difficult exit, leadership transition or employee relations case they've never personally run before.</p>","title":""},{"description":"<p>Led by someone who cares about the mission and knows better than to expect employees to feel the same way about a pay cheque. People show up to learn something, earn something, or simply be respected, heard and motivated to succeed. Every one of those reasons is fair. Roughly 50 to 2,000 people, where these decisions currently land on whoever's most senior and available, rather than a dedicated HRBP.</p>","title":""},{"description":"<p>A founder who wants a trusted, confidential pair of hands before a sensitive decision goes public.</p>","title":""},{"description":"<p>On the first call, this is the thing I'm listening for: was the employee part of the decision, or just the paperwork after it.</p>","title":""}],"subtitle":"Built for the moment a people decision gets too sensitive to delegate.","subtitle_handwritten":true,"title_lines":[],"step_style":"cards","subtitle_as_title":true,"last_step_as_note":true},"id":"8317b9a4-398d-4f37-977f-fdb60e5bf0f5","type":"process_steps"}]}],"id":"09d16592-d05f-4f9a-9af8-cb23e7a89256"}],"id":"df18c518-c9a7-4cf2-9fb4-67a79aecaeff","layout":{"alignment":"left","column_widths":[100],"columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false,"spaceTop":"full","spaceBottom":"near"},"schema_version":3,"strip_title":"Who this is for"},{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"5cd633fd-cf7c-418e-8d32-181af9c03438","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"__design":{"bgColor":"","borderRadius":0,"customCss":"","marginBottom":0,"marginLeft":0,"marginRight":0,"marginTop":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"visibility":{"desktop":true,"mobile":true}},"caption_position":"bottom-left","color_caption_bg":"","color_caption_text":"","color_description":"","color_eyebrow":"","color_title":"","description":"<p>Picture the room this happens in: a redundancy list open on a screen, a comp decision about to set precedent, an exit that has to go right the first time. Someone senior enough to have run this before sits at the table, asking the one question the moment needs.</p><p>That is the work: a senior human presence for the call itself, holding the judgement a policy folder was always going to miss.</p>","eyebrow":"What good looks like","floating_caption":"","image_alt":"A private conversation, lit by a single source of light.","image_position":"right","image_shape":"default","image_url":"https://mbxqjjmjywsxibttjrgr.supabase.co/storage/v1/object/public/media-library/fractional-hrbp-1788701933660-mqm07v.jpg","split_widths":[67,33],"title":"The senior voice in the room when the moment is too sensitive to delegate.","title_lines":["<p>The senior voice in the room when the moment is <span class=\"mc-accent\">too sensitive to delegate.</span></p>"],"panel_style":"pillar","pillar":"fractional-hrbp"},"id":"821d16dd-62b3-41b3-9ebe-ea870840109c","type":"image_text"}]}],"id":"fc472e89-4569-4aaa-9de0-7cf7b69d967a"}],"id":"a1e5f3c2-9b7d-4e6a-8c4f-2d1b6e9a3f70","layout":{"alignment":"left","columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":56,"paddingTop":56,"snapEnabled":false},"schema_version":3,"scope":null,"strip_title":"What Good Looks Like"},{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"7af9eb5e-be49-495f-aabd-ac6d029010cf","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"cards":[{"body":"A restructure or a difficult exit lands on whoever's most senior in the room, moving fast, with everyone learning the plan as it happens. The moment passes quickly, and it only gets one chance to go well. A restructure teaches the whole company how it will be treated when things get hard. That lesson outlives the restructure.","icon":"lucide:CircleAlert","title":"The problem","variant":"dark"},{"body":"Three redundancy rounds, run across 36 countries, supporting roughly 500 employees through the process. That is the judgement a fractional HRBP brings into the room: someone who has already sat through the version of this conversation that goes wrong, and knows exactly what makes it go right.","icon":"lucide:GraduationCap","title":"A background built for exactly this call","variant":"glass"},{"body":"A social sciences background (anthropology, sociology, media and communication) built around reading how people experience a hard moment, alongside the legal and procedural side of it. Confidential, fast to start, and squarely on your side.","icon":"lucide:HeartHandshake","title":"Someone who understands the employee behind the process","variant":"glass"}],"color_card_body":"","color_card_title":"","eyebrow":"Why The Magic Coffin","title_lines":["<p>Here's the problem, and here's the fix.</p>"],"marker_style":"bar"},"id":"3d00a6ca-5cb7-4fc0-a005-40218a145af8","type":"boxed"}]}],"id":"e4a8af15-98f7-4b57-9ec2-eeb11575dce9"}],"id":"e7822069-e8ed-4c09-9399-ccdc1c189423","layout":{"alignment":"left","columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":56,"paddingTop":56,"snapEnabled":false,"spaceTop":"full","spaceBottom":"tight"},"schema_version":3,"scope":null,"strip_title":"Why The Magic Coffin"},{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"rs-af1fa434-1061-4693-9c21-0f3b7b1ec8aa-service-cell0","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"card_text_align":"left","color_card_bg":"","color_card_description":"","color_card_title":"","color_carousel_btn_bg":"","color_carousel_btn_fg":"","color_cta_text":"","color_cta_time":"","color_deliverables_bg":"","color_deliverables_label":"","color_divider_from":"","color_divider_to":"","color_dot_active":"","color_dot_inactive":"","color_heading":"","color_heading_sub":"","color_label":"","color_meta_bg":"","color_meta_fg":"","color_note_border":"","color_primary":"","color_section_bg":"","color_subtitle":"","description":"<p>Every engagement starts with a free 30-minute call, where you get a straight answer including an honest read on fit.</p>","eyebrow":"Engagements","pillar_number":"Pillar 04","services":[{"deliverables":["Initial situation assessment and risk read","Coordination advisory alongside your legal counsel","Communication drafting support: letters, scripts, FAQs for the moment at hand","Manager briefing and coaching specific to the situation","Written documentation of the process, so the next one starts from a playbook"],"description":"One defined hard moment, handled end to end by someone who has run this before: a restructure, a difficult exit, a policy crisis, a leadership transition, an employee relations case. You get support for the specific thing in front of you, and a monthly partnership stays open for later. Done looks like: a situation assessment and risk read inside 48 hours of kickoff, the letters, scripts and FAQs drafted for the moment itself, your managers briefed, and the process documented so the next one starts from something.","price":"Book a free consultation","subtitle":"Single Hard-Moment Support","tag":"Fixed engagement","tagType":"fixed","time":"From €500 a day · Three-day minimum · Scoped per engagement","title":"The Vigil","startHere":"start here"},{"deliverables":["Monthly strategy session with founder or leadership","Employee relations case support and advisory","Manager coaching on the conversations that get avoided","Advisory input on comp, promotion and restructure decisions","Policy interpretation and guidance as situations come up","Honest culture and engagement read-outs to leadership"],"description":"The flagship of this pillar: an embedded strategic partner who sits across the table from you monthly. Advising on the calls too sensitive to delegate, coaching your managers through the conversations they're avoiding, reading the culture before it shows up as a resignation trend, and handling comp, promotion and restructure decisions with someone who has sat on both sides of a redundancy process. Done looks like, every month: a strategy session held, live employee relations cases carried, managers coached through the conversations they have been avoiding, and an honest culture read-out delivered to leadership.","note":"The 3-month minimum is there for your benefit: trust in this kind of work takes more than one meeting.","price":"Book a free consultation","subtitle":"Fractional HRBP · People Partnering","tag":"Monthly Retainer","tagType":"retainer","time":"From €650 a month · Minimum 3-month commitment · ~10–16 hrs/mo","title":"The Resurrection"}],"title":"What we can help you with","card_layout":"grid","pillar":"fractional-hrbp"},"id":"d00313a8-c885-449e-bc68-c69184a936e0","type":"service"}]}],"id":"rs-af1fa434-1061-4693-9c21-0f3b7b1ec8aa-service-col"}],"id":"af1fa434-1061-4693-9c21-0f3b7b1ec8aa","layout":{"alignment":"left","column_widths":[100],"columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false,"spaceTop":"full","spaceBottom":"tight"},"schema_version":3,"strip_title":"Engagements"},{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"rs-af1fa434-1061-4693-9c21-0f3b7b1ec8aa-faq-cell0","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"eyebrow":"FAQ","items":[{"answer":"<p>This sits alongside legal advice, as a complement to it rather than a substitute.</p><p>Legal counsel tells you what's compliant. A fractional HRBP tells you how it's likely to land with the people affected, and helps you say it well.</p><p>Plenty of hard moments call for both.</p>","question":"Is this a replacement for our employment lawyer?"},{"answer":"<p>For The Vigil, situation assessment happens within 48 hours of kickoff.</p><p>This pillar is built around the reality that these situations are rarely convenient to wait on.</p>","question":"How fast can you start once we call?"},{"answer":"<p>Yes. Confidentiality is the load-bearing term of this entire pillar.</p><p>A mutual NDA is signed before the situation assessment begins, first thing, ahead of anything else.</p>","question":"Is everything discussed confidential, including from other stakeholders in the business?"},{"answer":"<p>It gets re-scoped honestly and immediately, out in the open rather than folded quietly into the original quote.</p><p>You'll know as soon as the shape of the work changes, with the option to adjust or stop.</p>","question":"What happens if the situation escalates beyond what was originally scoped?"},{"answer":"<p>A senior HR Business Partner who works with you part time or per engagement instead of full time.</p><p>The judgement of a senior hire on restructures, employee relations and comp decisions, at a fraction of the cost and commitment.</p>","question":"What is a fractional HRBP, exactly?"},{"answer":"<p>Both exist.</p><p>The Vigil is a single hard-moment engagement, scoped and priced per situation.</p><p>The Resurrection is a monthly retainer with a three-month minimum, for ongoing strategic partnership rather than one fire to put out.</p>","question":"How is this priced, day rate or retainer?"},{"answer":"<p>A fractional CPO usually owns the whole People function and strategy end to end, often across several clients at once.</p><p>A fractional HRBP, this pillar, brings judgement to specific, high-stakes calls: a restructure, a difficult exit, a comp decision that sets precedent, while the function itself stays owned in-house.</p><p>Plenty of companies need the second long before they can justify or find the first.</p>","question":"What's the difference between a fractional CPO and a fractional HRBP?"},{"answer":"<p>Yes, as separate services. <a href=\"/services/manager-enablement/\">Manager Enablement</a> trains a whole group of new managers with a kit, a cohort and coaching. <a href=\"/services/pay-transparency/\">Pay Transparency</a> builds job levels, pay bands and the pay conversation for the EU Pay Transparency Directive.</p><p>Fractional HRBP covers the individual calls in between, and the three work well together.</p>","question":"Can you also train our managers or sort out our pay structure?"}],"title_lines":["<p>Frequently asked questions</p>"],"subtitle":"If yours isn't here, that's what the free consultation is for."},"id":"8388edc9-5e4d-47d3-bb9a-6ea646c6fde1","type":"faq"}]}],"id":"rs-af1fa434-1061-4693-9c21-0f3b7b1ec8aa-faq-col"}],"id":"rs-af1fa434-1061-4693-9c21-0f3b7b1ec8aa-faq","layout":{"alignment":"left","column_widths":[100],"columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false,"spaceTop":"full","spaceBottom":"tight"},"schema_version":3,"strip_title":"FAQ"},{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"8bb64731-2b60-452c-accc-2e510adb298a","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"body":"<p></p>","categories":["People & HR Compliance"],"color_eyebrow":"","color_title":"","eyebrow":"Latest thinking","limit":3,"link_label":"All blogs & insights","title":"From the blog","title_lines":[]},"id":"a5ebd2a5-9a14-414b-84a1-8721d701578e","type":"from_the_blog"}]}],"id":"82917e75-45b8-4bca-ac1b-2e5dffdc104b"}],"id":"d68d765d-3290-4fc2-8e05-0e73d1fb78ed","layout":{"alignment":"left","column_widths":[100],"columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false,"spaceTop":"full","spaceBottom":"none"},"schema_version":3,"strip_title":"From the blog"},{"bg_color":"","column_layout":"custom","columns":[{"cell_direction":"vertical","cells":[{"id":"gap-contact-fractional-hrbp-cell","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"body":"Book a free 30-minute consultation. We'll identify your biggest vampire moment and tell you honestly whether we're the right fit to bury it.","button_text":"Book a free consultation","fields":[{"key":"name","label":"Your name","required":true,"type":"text","visible":true},{"key":"email","label":"Email address","required":true,"type":"email","visible":true},{"key":"company","label":"Company","required":false,"type":"text","visible":true},{"key":"message","label":"Tell us about your vampire moment","required":true,"type":"textarea","visible":true},{"key":"marketing","label":"Keep me updated with insights and articles","required":false,"type":"checkbox","visible":true}],"show_social":false,"success_body":"We aim to respond within 24 hours. Keep an eye out on your mailbox!","success_button":"Send another message","success_heading":"Thanks for making the first step!","title_lines":["<p>Not sure where to start?</p>","<p><span class=\"mc-accent\">Lift the lid first.</span></p>"],"stamp":"Lid off"},"id":"gap-contact-fractional-hrbp-widget","type":"contact"}]}],"id":"gap-contact-fractional-hrbp-col"}],"customCss":null,"id":"gap-contact-fractional-hrbp","layout":{"alignment":"left","columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false,"spaceTop":"full","spaceBottom":"full"},"schema_version":3,"scope":null,"strip_title":"Contact"}]$mc$::jsonb where slug = 'services/fractional-hrbp';
update public.cms_pages set draft_page_rows = $mc$[{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"0d1e334e-6141-42e9-9e77-96923794bc9a","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"align":"left","answer":"Manager enablement for companies of 20 to 2,000 people promoting their first or next wave of managers. I build the manager kit, run small cohorts and coach new managers one to one, remote-first from Sweden, for teams anywhere.","body":"<p>Plenty of growing companies make managers the same way: the best specialist gets a team and a calendar full of one-to-ones. From that day, managers carry every message, every pay question and every hard conversation, usually with a 12-page PDF as their only guide.</p><p>We give them a kit they'll use, a small group of peers to practise with, and a clinic for the questions that arrive later. Your managers grow confident, and your people hear the same story from every team.</p>","color_label":"#6A010E","label":"Manager Enablement","title_lines":["<p><span style=\"color: rgb(106, 1, 14)\">Promoted on Tuesday. Managing by Wednesday.</span></p>","<p><span style=\"color: rgb(106, 1, 14)\">Googling \"how to give feedback\" by Friday.</span></p>"],"visual_image_alt":"A person holding a flashlight beam up to the night sky","visual_image_url":"https://mbxqjjmjywsxibttjrgr.supabase.co/storage/v1/object/public/media-library/people-flashlight-beam-milky-way-night-1788599992393-g6r4d1.jpg","visual_layout":"half_bleed","title_size":"compact","label_dot":true,"cta_label":"Book a free consultation","cta_url":"/#contact","answer_strip":true,"visual_badge_label":"Start with","visual_badge_title":"The Grimoire","visual_badge_text":"Manager Starter Kit · From €900"},"id":"d796eb20-bf0e-4b2e-9563-787205372e07","type":"hero"}]}],"id":"5b165550-f6b3-4652-907d-6e8cf10c4516"}],"id":"cac1d6db-4e06-425d-826f-deb998333943","layout":{"alignment":"left","column_widths":[100],"columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false,"spaceTop":"lead","spaceBottom":"none"},"schema_version":3,"strip_title":"Hero"},{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"693763b5-2137-4b5c-a630-a40f2f0ba761","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"body":"<p></p>","eyebrow":"WHO IS THIS FOR","steps":[{"description":"<p>Founders and People leads at companies of 20 to 2,000 people, promoting brilliant specialists into their first management role.</p>","title":""},{"description":"<p>Scale-ups where company news reaches some teams in an hour and others in a week, depending on who their manager is.</p>","title":""},{"description":"<p>Teams heading into something hard (a restructure, a pay change, a review cycle) where managers will carry the conversations.</p>","title":""},{"description":"<p>On the first call, this is the thing I'm listening for: who do your managers call when they're stuck, and how often is it you.</p>","title":""}],"subtitle":"Built for the company whose managers learned the job on the job.","subtitle_handwritten":true,"title_lines":[],"step_style":"cards","subtitle_as_title":true,"last_step_as_note":true},"id":"e4c30ab9-9c37-4ad0-9065-b4f419b09e0f","type":"process_steps"}]}],"id":"1ad4255d-c547-4868-b32e-08fe9b131809"}],"id":"0d52adba-62ca-4015-a4fd-895d5d220e0d","layout":{"alignment":"left","column_widths":[100],"columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false,"spaceTop":"full","spaceBottom":"near"},"schema_version":3,"strip_title":"How We Work"},{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"ca45200e-125c-4f65-a22a-4a601b291984","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"__design":{"bgColor":"","borderRadius":0,"customCss":"","marginBottom":0,"marginLeft":0,"marginRight":0,"marginTop":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"visibility":{"desktop":true,"mobile":true}},"caption_position":"bottom-left","color_caption_bg":"","color_caption_text":"","color_description":"","color_eyebrow":"","color_title":"","description":"<p>The one-to-one, the feedback, the bad news: each one goes better with a script and a rehearsal behind it.</p><p>We write the scripts and run the rehearsals, so your managers walk in ready.</p>","eyebrow":"What good looks like","floating_caption":"","image_alt":"Blurred figures walking through a corridor of arches","image_position":"left","image_shape":"default","image_url":"https://mbxqjjmjywsxibttjrgr.supabase.co/storage/v1/object/public/media-library/people-blurred-motion-figures-corridor-arches-1788703492024-s4xepo.jpg","split_widths":[33,67],"title":"Managers who know what to say.","title_lines":["<p>Managers who know what to <span class=\"mc-accent\">say.</span></p>"],"panel_style":"pillar","pillar":"manager-enablement"},"id":"0cc222f8-287b-4c74-bb3d-5095a5b2d51a","type":"image_text"}]}],"id":"84e9963a-8340-4c79-b553-97c879f77e7d"}],"id":"43d4337c-d06e-42ea-b4f2-fb756d9582b2","layout":{"alignment":"left","columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":56,"paddingTop":56,"snapEnabled":false},"schema_version":3,"strip_title":"What Good Looks Like"},{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"f83c69de-5738-47ea-9d8c-d6dd825fd3c7","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"cards":[{"body":"A new manager gets the title, the team and the calendar in a single afternoon. The training usually arrives months later, while the team is already deciding whether to stay. In the UK, only 18% of new managers get formal training, and people with an ineffective manager are more than twice as likely to plan to leave.","icon":"lucide:CircleAlert","title":"The problem","variant":"dark"},{"body":"Years of writing manager briefings for restructures across 36 countries, and training branch staff in banking before that. The kit comes from what managers asked for in the moment, when the news was hard and the clock was running.","icon":"lucide:Users","title":"A background built for exactly this","variant":"glass"},{"body":"A social sciences background (anthropology, sociology, media and communication) means the programme works with how people learn from each other, through practice and peers, alongside the slides.","icon":"lucide:GraduationCap","title":"Someone who understands how people learn","variant":"glass"}],"eyebrow":"Why The Magic Coffin","title_lines":["<p>Here's the problem, and here's the fix.</p>"],"marker_style":"bar"},"id":"32a2bcd6-d630-4519-bb80-1f5ec25d4538","type":"boxed"}]}],"id":"c4a66278-5617-45a9-a3d6-cf5e403207c7"}],"id":"d7c3da0a-b963-42d4-b532-e6b82dcb6fe8","layout":{"alignment":"left","columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":56,"paddingTop":56,"snapEnabled":false,"spaceTop":"full","spaceBottom":"tight"},"schema_version":3,"strip_title":"Why The Magic Coffin"},{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"rs-f6e7ac0a-83a7-434e-9351-04da58518ed2-service-cell0","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"card_text_align":"left","color_card_bg":"","color_card_description":"","color_card_title":"","color_carousel_btn_bg":"","color_carousel_btn_fg":"","color_cta_text":"","color_cta_time":"","color_deliverables_bg":"","color_deliverables_label":"","color_divider_from":"","color_divider_to":"","color_dot_active":"","color_dot_inactive":"","color_heading":"","color_heading_sub":"","color_label":"","color_meta_bg":"","color_meta_fg":"","color_note_border":"","color_primary":"","color_section_bg":"","color_subtitle":"","description":"<p>Every engagement starts with a free 30-minute call, where you get a straight answer including an honest read on fit.</p>","eyebrow":"Engagements","pillar_number":"Pillar 06","services":[{"deliverables":["One-to-one template and a first-90-days checklist for new managers","Feedback scripts, including the uncomfortable ones","Briefing template for passing on company news within 24 hours","\"What to say when\" cards: pay questions, a resignation, a restructure rumour, a wellbeing conversation","One-page manager version of each key people policy","A \"who to call\" page for everything else"],"description":"Every manager needs a book of spells. The Grimoire is a written kit, adapted to your company's tools and tone: templates, scripts and one-page cards for the moments managers dread. Done looks like: every manager holding the same kit, and every key people policy turned into a one-page \"what do I say\" card.","note":"The natural starting point, and the kit every Coven cohort works from.","price":"Book a free consultation","subtitle":"Manager Starter Kit","tag":"Fixed project","tagType":"fixed","time":"From €900 · 2–3 weeks · ~18–24 hours","title":"The Grimoire","startHere":"start here"},{"deliverables":["The Grimoire, included","Four 90-minute sessions: one-to-ones and feedback; passing on news and change; pay and performance conversations; hard moments","Peer pairs between sessions","Upward-feedback pulse before session one and after session four","Results report, with turnover and absence to track over the following six months"],"description":"Up to 12 managers, four sessions, eight weeks. Each session takes one hard part of the job, and managers practise on each other before they try it with their teams. An upward-feedback pulse before and after shows everyone what changed. Done looks like: every manager has rehearsed the four conversations, and their teams' feedback is measured before and after.","price":"Book a free consultation","subtitle":"Manager Cohort Programme","tag":"Fixed project","tagType":"fixed","time":"From €2,000 · 8 weeks · ~40–50 hours","title":"The Coven"},{"deliverables":["Six 60-minute coaching sessions","Preparation for real upcoming conversations","The Grimoire kit","Short written notes after each session","A three-way check-in with their own manager at the end"],"description":"Some managers need a companion more than a classroom. The Familiar pairs one new manager with six coaching sessions over six weeks, built around the real conversations in their diary. Done looks like: a manager who has prepared, run and reviewed their hardest upcoming conversations with support at every step.","price":"Book a free consultation","subtitle":"One-to-One Coaching for New Managers","tag":"Fixed project","tagType":"fixed","time":"From €600 · 6 weeks · ~10–12 hours","title":"The Familiar"},{"deliverables":["Monthly two-hour group clinic","Shared channel for questions, answered within two working days","Kit onboarding for each new manager","Quarterly kit refresh","Monthly note: themes, risks and anything that needs a decision from you"],"description":"Habits fade once a programme ends, most often when the manager who owned them moves on. The Night School keeps them going: a monthly two-hour group clinic, a shared channel for questions between sessions, and onboarding for every new manager who joins. Done looks like, every month: a clinic held, every question answered within two working days, and every new manager given the kit in their first week.","note":"The 3-month minimum is a commitment to the habit forming.","price":"Book a free consultation","subtitle":"Monthly Manager Clinic","tag":"Monthly Retainer","tagType":"retainer","time":"From €400 a month · Minimum 3-month commitment · ~6–8 hrs/mo","title":"The Night School"}],"title":"What we can help with","card_layout":"grid","pillar":"manager-enablement"},"id":"cfcc589a-a9dd-4dda-9c62-b019f9af9925","type":"service"}]}],"id":"rs-f6e7ac0a-83a7-434e-9351-04da58518ed2-service-col"}],"id":"f6e7ac0a-83a7-434e-9351-04da58518ed2","layout":{"alignment":"left","column_widths":[100],"columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false,"spaceTop":"full","spaceBottom":"tight"},"schema_version":3,"strip_title":"Engagements"},{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"rs-f6e7ac0a-83a7-434e-9351-04da58518ed2-faq-cell0","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"body":"<p></p>","eyebrow":"FAQ","items":[{"answer":"<p>Manager Enablement is built from your company's own policies, tools and moments.</p><p>Managers practise the conversations they'll have next week, with colleagues who share the context, and leave with a kit written for your company.</p>","question":"How is this different from a leadership course?"},{"answer":"<p>Four to twelve works best.</p><p>With fewer managers, The Familiar gives the same practice one to one, and The Grimoire works at any size.</p>","question":"How many managers do we need for a Coven?"},{"answer":"<p>Online by default, with in-person sessions where the trip earns its place.</p>","question":"Is it online or in person?"},{"answer":"<p>Agreed at the start: an upward-feedback pulse from each manager's team before and after, plus staff turnover and absence over the following six months.</p>","question":"How do you measure whether it worked?"},{"answer":"<p>Yes. Sessions and scripts can be built around the change coming up, so managers rehearse the exact conversations they're about to have.</p><p>It pairs well with <a href=\"/services/internal-communications/\">Internal Communications</a> and <a href=\"/services/pay-transparency/\">Pay Transparency</a> work.</p>","question":"Can it cover a specific change, such as a restructure or a pay review?"},{"answer":"<p>The focus is first-time and newer managers.</p><p>For senior leaders facing a sensitive decision, <a href=\"/services/fractional-hrbp/\">Fractional HRBP</a> brings a senior partner into the room.</p>","question":"Is this coaching for senior leaders too?"},{"answer":"<p>Manager enablement gives new managers the tools, practice and support for the people side of the job: one-to-ones, feedback, passing on company news and hard conversations.</p><p>At The Magic Coffin it runs as a written kit (The Grimoire), an eight-week cohort (The Coven), one-to-one coaching (The Familiar) and a monthly clinic (The Night School).</p>","question":"What is manager enablement?"}],"title_lines":["<p>Frequently asked questions</p>"],"subtitle":"If yours isn't here, that's what the free consultation is for."},"id":"23fee244-8abc-426c-a14f-0d4f24976128","type":"faq"}]}],"id":"rs-f6e7ac0a-83a7-434e-9351-04da58518ed2-faq-col"}],"id":"rs-f6e7ac0a-83a7-434e-9351-04da58518ed2-faq","layout":{"alignment":"left","column_widths":[100],"columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false,"spaceTop":"full","spaceBottom":"tight"},"schema_version":3,"strip_title":"FAQ"},{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"635a7b57-cd5d-46be-8896-2024ced833b8","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"categories":["People Experience"],"color_eyebrow":"","color_title":"","eyebrow":"Latest thinking","limit":3,"link_label":"All blogs & insights","title":"From the blog"},"id":"7387e80b-94d2-436a-b258-81ca9222e50a","type":"from_the_blog"}]}],"id":"80b2aa1e-bcab-4b2d-ad61-5de260969350"}],"id":"52c37da6-4799-4803-bec1-c776c59d9ed8","layout":{"alignment":"left","column_widths":[100],"columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false,"spaceTop":"full","spaceBottom":"none"},"schema_version":3,"strip_title":"From the blog"},{"bg_color":"","column_layout":"custom","columns":[{"cell_direction":"vertical","cells":[{"id":"gap-contact-manager-enablement-cell","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"body":"Book a free 30-minute consultation. We'll identify your biggest vampire moment and tell you honestly whether we're the right fit to bury it.","button_text":"Book a free consultation","fields":[{"key":"name","label":"Your name","required":true,"type":"text","visible":true},{"key":"email","label":"Email address","required":true,"type":"email","visible":true},{"key":"company","label":"Company","required":false,"type":"text","visible":true},{"key":"message","label":"Tell us about your vampire moment","required":true,"type":"textarea","visible":true},{"key":"marketing","label":"Keep me updated with insights and articles","required":false,"type":"checkbox","visible":true}],"show_social":false,"success_body":"We aim to respond within 24 hours. Keep an eye out on your mailbox!","success_button":"Send another message","success_heading":"Thanks for making the first step!","title_lines":["<p>Not sure where to start?</p>","<p><span class=\"mc-accent\">Lift the lid first.</span></p>"],"stamp":"Lid off"},"id":"gap-contact-manager-enablement-widget","type":"contact"}]}],"id":"gap-contact-manager-enablement-col"}],"customCss":null,"id":"gap-contact-manager-enablement","layout":{"alignment":"left","columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false,"spaceTop":"full","spaceBottom":"full"},"schema_version":3,"scope":null,"strip_title":"Contact"}]$mc$::jsonb where slug = 'services/manager-enablement';
update public.cms_pages set draft_page_rows = $mc$[{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"b9bb590f-0a6c-4c81-b5f7-34eef5d9dc8d","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"align":"left","answer":"The Magic Coffin offers six ways into the same problem: people who stopped listening. Start with internal communications if the message is the issue, employee experience if the journey is, people operations if the systems are, pay transparency if the pay structure is, manager enablement if your managers are, or a fractional HR business partner if you need all of it from one senior person.","body":"<p>Depending on which one's currently draining you.</p>","label":"HOW WE BRING THE COFFIN","title_lines":["<p>Six ways in.</p>"],"title_size":"display","visual_image_url":"https://mbxqjjmjywsxibttjrgr.supabase.co/storage/v1/object/public/media-library/services-index-1788701976367-9x42xy.jpg","visual_image_alt":"Brutalist stone pillars representing The Magic Coffin's consulting service pillars","visual_layout":"half_bleed","body_size":"large","cta_label":"Book a free consultation","cta_url":"#contact"},"id":"71349a1b-d2dd-4ecb-a380-f69fbbea8e61","type":"hero"}]}],"id":"c4e641ef-a920-45cb-a7ea-cc1b1e7505a5"}],"id":"57190476-48f4-48a2-811f-34242f59237b","layout":{"alignment":"left","column_widths":[100],"columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false,"spaceTop":"lead","spaceBottom":"none"},"schema_version":3,"strip_title":"Hero"},{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"cell_services_index","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"__design":{"bgColor":"","borderRadius":0,"customCss":"","marginBottom":0,"marginLeft":0,"marginRight":0,"marginTop":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"visibility":{"desktop":true,"mobile":true}},"cards":[{"body":"<p>Audits, strategy and fractional leadership for messages people read, remember and act on.</p>","icon":"lucide:Building2","link_url":"/services/internal-communications","title":"Internal Communications","variant":"pillar","meta":"The Autopsy · The Burial · The Resurrection","price":"€900","price_note":"start with The Autopsy, from"},{"body":"<p>Onboarding, journeys and surveys people actually finish, still running long after week one.</p>","icon":"lucide:Star","link_url":"/services/employee-experience","title":"Employee Experience","variant":"pillar","meta":"The Autopsy · The Awakening · The Séance · The Resurrection","price":"€900","price_note":"start with The Autopsy, from"},{"body":"<p>The operational skeleton that lets your company run on written processes instead of one person's memory and a shared spreadsheet.</p>","icon":"lucide:Settings2","link_url":"/services/people-operations","title":"People Operations","variant":"pillar","meta":"The Autopsy · The Reanimation · The Covenant · The Resurrection","price":"€900","price_note":"start with The Autopsy, from"},{"body":"<p>A senior partner in the room for the calls too sensitive to delegate, for a fraction of a full-time hire.</p>","icon":"lucide:HeartHandshake","link_url":"/services/fractional-hrbp","title":"Fractional HRBP","variant":"pillar","meta":"The Vigil · The Resurrection","price":"€500 a day","price_note":"start with The Vigil, from"},{"body":"<p>Job levels, pay bands and pay answers your managers can explain, ready for the EU Pay Transparency Directive.</p>","icon":"lucide:Scale","link_url":"/services/pay-transparency","title":"Pay Transparency","variant":"pillar","meta":"The Autopsy · The Unmasking · The Reckoning · The Ledger","price":"€750","price_note":"start with The Autopsy, from"},{"body":"<p>A manager kit, small peer cohorts and one-to-one coaching for the specialists you just promoted.</p>","icon":"lucide:Users","link_url":"/services/manager-enablement","title":"Manager Enablement","variant":"pillar","meta":"The Grimoire · The Coven · The Familiar · The Night School","price":"€900","price_note":"start with The Grimoire, from"}],"eyebrow":"Our services","layout_mode":"list","subtitle":"","subtitle_color":"","subtitle_handwritten":false,"title_lines":["<p>Six pillars, one specialist, <span class=\"mc-accent\">no hand-offs.</span></p>"],"intro":"<p>Internal comms, employee experience, people operations, fractional HRBP, pay transparency and manager enablement are six different disciplines, and they all run through the same head: yours, or ours.</p><p>Pick a pillar below, or book a free consultation and we'll find the right one together.</p>"},"id":"widget_services_index","type":"boxed"}]}],"id":"col_services_index"}],"id":"row_services_index","layout":{"alignment":"left","columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false,"verticalAlign":"middle"},"schema_version":3,"strip_title":"Services"},{"bg_color":"","column_layout":"100","columns":[{"cell_direction":"vertical","cells":[{"id":"610770ec-1fd4-4e0d-9ab4-4745e3e55d18","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"eyebrow":"FAQ","items":[{"answer":"<p>Plenty of real problems do. Internal comms and employee experience overlap constantly, and people operations underpins both. Pay transparency and manager enablement travel together too: your managers are the ones who answer the pay questions.</p><p>Book the free call and describe the actual symptom rather than the pillar you think it belongs to. We'll tell you where to start.</p>","question":"What if my problem spans more than one pillar?"},{"answer":"<p>If people are missing what you tell them: Internal Communications.</p><p>If people are leaving, or barely arriving in the first place: Employee Experience.</p><p>If every process only runs because you personally remember it: People Operations.</p><p>If the decision in front of you is too sensitive to delegate and too rare to hire for: Fractional HRBP.</p><p>If pay gets set case by case and you now need a structure you can explain out loud: Pay Transparency.</p><p>If your newest managers are learning the job by guessing: Manager Enablement.</p>","question":"Which pillar should I start with if I'm not sure?"}],"title_lines":["<p>Not sure which one you need?</p>"]},"id":"01e84fde-9b5f-44af-a885-96b3b8e839fa","type":"faq"}]}],"id":"343cf28f-964b-4160-b7cd-88c8ac4d758c"}],"id":"e587dda7-220e-4778-95bf-376ccb2a9cfe","layout":{"alignment":"left","column_widths":[100],"columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false,"spaceTop":"none","spaceBottom":"none"},"schema_version":3,"strip_title":"FAQ"},{"bg_color":"","column_layout":"custom","columns":[{"cell_direction":"vertical","cells":[{"id":"gap-contact-services-cell","layout":{"direction":"vertical","gap":24,"justify":"stretch","minHeight":0,"paddingBottom":0,"paddingLeft":0,"paddingRight":0,"paddingTop":0,"verticalAlign":"top"},"span":{"col":1,"row":1},"style":{"bgColor":"","borderColor":"","borderRadius":0,"borderWidth":0,"customClass":"","customCss":""},"widgets":[{"data":{"body":"Book a free 30-minute consultation. We'll identify your biggest vampire moment and tell you honestly whether we're the right fit to bury it.","button_text":"Book a free consultation","fields":[{"key":"name","label":"Your name","required":true,"type":"text","visible":true},{"key":"email","label":"Email address","required":true,"type":"email","visible":true},{"key":"company","label":"Company","required":false,"type":"text","visible":true},{"key":"message","label":"Tell us about your vampire moment","required":true,"type":"textarea","visible":true},{"key":"marketing","label":"Keep me updated with insights and articles","required":false,"type":"checkbox","visible":true}],"show_social":false,"success_body":"We aim to respond within 24 hours. Keep an eye out on your mailbox!","success_button":"Send another message","success_heading":"Thanks for making the first step!","title_lines":["<p>Not sure where to start?</p>","<p><span class=\"mc-accent\">Lift the lid first.</span></p>"],"stamp":"Lid off"},"id":"gap-contact-services-widget","type":"contact"}]}],"id":"gap-contact-services-col"}],"customCss":null,"id":"gap-contact-services","layout":{"alignment":"left","columns":1,"fullWidth":false,"marginBottom":0,"marginTop":0,"paddingBottom":64,"paddingTop":64,"snapEnabled":false,"spaceTop":"full","spaceBottom":"full"},"schema_version":3,"scope":null,"strip_title":"Contact"}]$mc$::jsonb where slug = 'services';
